const ParsedGlobalQueryTable = struct {
    parsed: std.json.Parsed(metadata_openapi.QueryRequest),
    table_name: []const u8,

    fn deinit(self: *@This()) void {
        self.parsed.deinit();
    }
};

fn parseGlobalQueryTable(alloc: std.mem.Allocator, body: []const u8) !ParsedGlobalQueryTable {
    var parsed = parsePublicGlobalQueryBody(alloc, body) catch return error.InvalidQueryRequest;
    errdefer parsed.deinit();
    return .{
        .parsed = parsed,
        .table_name = parsed.value.table orelse "",
    };
}

fn parsePublicGlobalQueryBody(alloc: std.mem.Allocator, body: []const u8) !std.json.Parsed(metadata_openapi.QueryRequest) {
    try query_contract.validatePublicQuerySortTupleContract(alloc, body);
    return metadata_openapi.server.parseGlobalQueryBody(alloc, body);
}

fn parsePublicTableQueryBody(alloc: std.mem.Allocator, body: []const u8) !std.json.Parsed(metadata_openapi.QueryRequest) {
    try query_contract.validatePublicQuerySortTupleContract(alloc, body);
    return metadata_openapi.server.parseQueryTableBody(alloc, body);
}

fn isNdjsonContentType(content_type: ?[]const u8) bool {
    const value = content_type orelse return false;
    const media_type = std.mem.trim(u8, if (std.mem.indexOfScalar(u8, value, ';')) |idx| value[0..idx] else value, " \t");
    return std.ascii.eqlIgnoreCase(media_type, "application/x-ndjson");
}

fn mcpSampleDocumentsJsonAlloc(alloc: std.mem.Allocator, ndjson: []const u8) ![]u8 {
    var out = std.ArrayListUnmanaged(u8).empty;
    errdefer out.deinit(alloc);
    try out.appendSlice(alloc, "{\"documents\":[");
    var lines = std.mem.splitScalar(u8, ndjson, '\n');
    var count: usize = 0;
    while (lines.next()) |raw_line| {
        const line = std.mem.trim(u8, raw_line, " \t\r");
        if (line.len == 0) continue;
        var parsed = try std.json.parseFromSlice(std.json.Value, alloc, line, .{});
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidScanResponse;
        if (count != 0) try out.append(alloc, ',');
        try out.appendSlice(alloc, line);
        count += 1;
    }
    try out.appendSlice(alloc, "]}");
    return try out.toOwnedSlice(alloc);
}

test "MCP document samples convert multiple NDJSON rows to one JSON value" {
    const alloc = std.testing.allocator;
    const body = try mcpSampleDocumentsJsonAlloc(
        alloc,
        "{\"_id\":\"doc:a\",\"body\":\"hello\"}\n{\"_id\":\"doc:b\",\"body\":\"world\"}\n",
    );
    defer alloc.free(body);
    try std.testing.expectEqualStrings(
        "{\"documents\":[{\"_id\":\"doc:a\",\"body\":\"hello\"},{\"_id\":\"doc:b\",\"body\":\"world\"}]}",
        body,
    );
}

const TestSseEvent = struct {
    event: []const u8,
