        return try BoundaryAbi.call("enable_extension", self.boundary_dispatch, fn_ptr, .{ self.ptr, alloc, name });
    }

    pub fn disableExtension(self: StatusSource, alloc: std.mem.Allocator, name: []const u8) !extension_domain.InstalledExtension {
        const fn_ptr = self.vtable.disable_extension orelse return error.UnsupportedOperation;
        return try BoundaryAbi.call("disable_extension", self.boundary_dispatch, fn_ptr, .{ self.ptr, alloc, name });
    }

    pub fn configureExtension(self: StatusSource, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.ConfigureExtensionRequest) !extension_domain.InstalledExtension {
        const fn_ptr = self.vtable.configure_extension orelse return error.UnsupportedOperation;
        return try BoundaryAbi.call("configure_extension", self.boundary_dispatch, fn_ptr, .{ self.ptr, alloc, name, req });
    }

    pub fn restoreExtensions(
        self: StatusSource,
        alloc: std.mem.Allocator,
        installed: []const extension_domain.InstalledExtension,
        members: []const extension_domain.ExtensionMember,
        dependencies: []const extension_domain.ExtensionDependency,
    ) !void {
        const fn_ptr = self.vtable.restore_extensions orelse return error.UnsupportedOperation;
        return try BoundaryAbi.call("restore_extensions", self.boundary_dispatch, fn_ptr, .{ self.ptr, alloc, installed, members, dependencies });
    }

    fn makeServiceVTable(comptime T: type) VTable {
        const Gen = struct {
            fn cast(ptr: *anyopaque) *T {
                return @ptrCast(@alignCast(ptr));
            }

            fn status(ptr: *anyopaque) anyerror!metadata_api.MetadataStatus {
                return try cast(ptr).status();
            }

            fn adminSnapshot(ptr: *anyopaque) anyerror!metadata_api.AdminSnapshot {
                return try cast(ptr).adminSnapshot();
            }

            fn cachedAdminSnapshot(ptr: *anyopaque) anyerror!?metadata_api.AdminSnapshot {
                return try cast(ptr).adminSnapshot();
            }

            fn linearizableSnapshot(ptr: *anyopaque, request: api_operation.RequestContext) anyerror!?metadata_api.AdminSnapshot {
                return try metadata_service.coherentLinearizableAdminSnapshot(T, cast(ptr), request);
            }

            fn freeAdminSnapshot(ptr: *anyopaque, snapshot: *metadata_api.AdminSnapshot) void {
                cast(ptr).freeAdminSnapshot(snapshot);
            }

            fn createTable(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, req: tables_api.CreateTableRequest) anyerror!void {
                return try createTableOnService(cast(ptr), alloc, table_name, req);
            }

            fn replaceTableDefinition(ptr: *anyopaque, expected: metadata_table_manager.TableRecord, replacement: metadata_table_manager.TableRecord) anyerror!void {
                return try replaceTableDefinitionOnService(cast(ptr), expected, replacement);
            }

            fn restoreTable(
                ptr: *anyopaque,
                alloc: std.mem.Allocator,
                table_name: []const u8,
                location_uri: []const u8,
                connection: []const u8,
                artifact_backup_id: []const u8,
                manifest: *const backups_api.TableBackupManifest,
            ) anyerror!void {
                return try persistRestoreTableIntent(cast(ptr), alloc, table_name, location_uri, connection, artifact_backup_id, manifest);
            }

            fn dropTable(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8) anyerror!void {
                return try dropTableOnService(cast(ptr), alloc, table_name);
            }

            fn updateSchema(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) anyerror!void {
                _ = try updateSchemaOnService(cast(ptr), alloc, table_name, schema_json);
            }

            fn updateSchemaVersioned(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) anyerror!u32 {
                return try updateSchemaOnService(cast(ptr), alloc, table_name, schema_json);
            }

            fn createIndex(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8, index_json: []const u8) anyerror!void {
                return try createIndexOnService(cast(ptr), alloc, table_name, index_name, index_json);
            }

            fn dropIndex(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8) anyerror!void {
                return try dropIndexOnService(cast(ptr), alloc, table_name, index_name);
            }

            fn putArtifactEnrichment(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, artifact_name: []const u8, enrichment_json: []const u8) anyerror!void {
                return try putArtifactEnrichmentOnService(cast(ptr), alloc, table_name, artifact_name, enrichment_json);
            }

            fn deleteArtifactEnrichment(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, artifact_name: []const u8) anyerror!void {
                return try deleteArtifactEnrichmentOnService(cast(ptr), alloc, table_name, artifact_name);
            }

            fn waitTableLifecycle(ptr: *anyopaque, table_name: []const u8, expected: TableVisibility) anyerror!void {
                return try cast(ptr).waitForTableLifecycle(table_name, switch (expected) {
                    .present => .present,
                    .absent => .absent,
                });
            }

            fn waitTableProjection(ptr: *anyopaque, table_name: []const u8, schema_json: ?[]const u8, indexes_json: ?[]const u8) anyerror!void {
                return try cast(ptr).waitForTableProjection(table_name, .{
                    .schema_json = schema_json,
                    .indexes_json = indexes_json,
                });
            }

            fn runRound(ptr: *anyopaque) anyerror!void {
                return try cast(ptr).runRound();
            }

            fn getJoinShuffleLease(ptr: *anyopaque, job_id: u64) anyerror!?metadata_table_manager.ShuffleJoinLeaseRecord {
                return try cast(ptr).getProjectedShuffleJoinLease(job_id);
            }

            fn upsertJoinShuffleLease(ptr: *anyopaque, record: metadata_table_manager.ShuffleJoinLeaseRecord) anyerror!void {
                try cast(ptr).upsertShuffleJoinLease(record);
            }

            fn removeJoinShuffleLease(ptr: *anyopaque, job_id: u64) anyerror!void {
                try cast(ptr).removeShuffleJoinLease(job_id);
            }

            fn installExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.InstallExtensionRequest) anyerror!extension_domain.InstalledExtension {
                return try installExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn updateExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.UpdateExtensionRequest) anyerror!extension_domain.InstalledExtension {
                return try updateExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn dropExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.DropExtensionRequest) anyerror!void {
                return try dropExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn enableExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8) anyerror!extension_domain.InstalledExtension {
                return try enableExtensionOnService(cast(ptr), alloc, name);
            }

            fn disableExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8) anyerror!extension_domain.InstalledExtension {
                return try disableExtensionOnService(cast(ptr), alloc, name);
            }

            fn configureExtension(ptr: *anyopaque, alloc: std.mem.Allocator, name: []const u8, req: extension_domain.ConfigureExtensionRequest) anyerror!extension_domain.InstalledExtension {
                return try configureExtensionOnService(cast(ptr), alloc, name, req);
            }

            fn restoreExtensions(
                ptr: *anyopaque,
                alloc: std.mem.Allocator,
                installed: []const extension_domain.InstalledExtension,
                members: []const extension_domain.ExtensionMember,
                dependencies: []const extension_domain.ExtensionDependency,
            ) anyerror!void {
                return try restoreExtensionsOnService(cast(ptr), alloc, installed, members, dependencies);
            }
        };

        return .{
            .status = Gen.status,
            .admin_snapshot = Gen.adminSnapshot,
            .cached_admin_snapshot = Gen.cachedAdminSnapshot,
            .linearizable_snapshot = Gen.linearizableSnapshot,
            .free_admin_snapshot = Gen.freeAdminSnapshot,
            .create_table = Gen.createTable,
            .replace_table_definition = Gen.replaceTableDefinition,
            .restore_table = Gen.restoreTable,
            .drop_table = Gen.dropTable,
            .update_schema = Gen.updateSchema,
            .update_schema_versioned = Gen.updateSchemaVersioned,
            .create_index = Gen.createIndex,
            .drop_index = Gen.dropIndex,
            .put_artifact_enrichment = Gen.putArtifactEnrichment,
            .delete_artifact_enrichment = Gen.deleteArtifactEnrichment,
            .wait_table_lifecycle = Gen.waitTableLifecycle,
            .wait_table_projection = Gen.waitTableProjection,
            .run_round = Gen.runRound,
            .get_join_shuffle_lease = Gen.getJoinShuffleLease,
            .upsert_join_shuffle_lease = Gen.upsertJoinShuffleLease,
            .remove_join_shuffle_lease = Gen.removeJoinShuffleLease,
            .install_extension = Gen.installExtension,
            .update_extension = Gen.updateExtension,
            .drop_extension = Gen.dropExtension,
            .enable_extension = Gen.enableExtension,
            .disable_extension = Gen.disableExtension,
            .configure_extension = Gen.configureExtension,
            .restore_extensions = Gen.restoreExtensions,
        };
    }

    pub fn fromMetadataHttpService(svc: *metadata_service.MetadataHttpService) StatusSource {
        return .{ .ptr = svc, .vtable = &comptime makeServiceVTable(metadata_service.MetadataHttpService) };
    }

    pub fn fromMetadataService(svc: *metadata_service.MetadataService) StatusSource {
        return .{ .ptr = svc, .vtable = &comptime makeServiceVTable(metadata_service.MetadataService) };
    }

    pub fn fromMetadataServer(srv: *metadata_server.MetadataServer) StatusSource {
        return fromMetadataHttpService(srv.svc);
    }
};

const RestoreMetadataSpec = struct {
    table: metadata_table_manager.TableRecord,
    ranges: []metadata_table_manager.RangeRecord,

    fn deinit(self: *RestoreMetadataSpec, alloc: std.mem.Allocator) void {
        metadata_table_manager.freeTable(alloc, self.table);
        for (self.ranges) |record| metadata_table_manager.freeRange(alloc, record);
        alloc.free(self.ranges);
        self.* = undefined;
    }
};

fn deriveRestoreMetadataSpec(
    alloc: std.mem.Allocator,
    table_name: []const u8,
    location_uri: []const u8,
    connection: []const u8,
    artifact_backup_id: []const u8,
    manifest: *const backups_api.TableBackupManifest,
) !RestoreMetadataSpec {
    try backups_api.validateRestoreManifest(alloc, manifest, manifest.backup_id);
    if (manifest.artifact_integrity_mode != .declared)
        return error.BackupIntegrityMissing;
    if (!std.mem.eql(u8, manifest.table_name, table_name)) return error.InvalidBackupRequest;
    const table = backups_api.deriveRestoreTableRecord(alloc, table_name, location_uri, manifest) catch |err| switch (err) {
        error.UnsupportedBackupMigrationState => return error.UnsupportedBackupMigrationState,
        else => return err,
    };
    errdefer metadata_table_manager.freeTable(alloc, table);
    const ranges = try backups_api.deriveRestoreRanges(alloc, table.table_id, location_uri, connection, artifact_backup_id, manifest);
    errdefer {
        for (ranges) |record| metadata_table_manager.freeRange(alloc, record);
        alloc.free(ranges);
    }
    return .{
        .table = table,
        .ranges = ranges,
    };
}

fn createTableOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, req: tables_api.CreateTableRequest) !void {
    var workflow = metadata_table_workflow.TableWorkflow.init(alloc);
    defer workflow.deinit();
    var normalized_req = req;
    var expanded_indexes_json: ?[]u8 = null;
    defer if (expanded_indexes_json) |value| alloc.free(value);
    const indexes_json = req.indexes_json orelse tables_api.default_indexes_json;
    expanded_indexes_json = try tables_api.expandSchemaDerivedAlgebraicIndexesAlloc(alloc, table_name, indexes_json, tables_api.effectiveSchemaJson(req.schema_json));
    normalized_req.indexes_json = expanded_indexes_json;
    const table = tables_api.deriveTableRecord(table_name, normalized_req);
    const ranges = try tables_api.deriveInitialRanges(alloc, table);
    defer {
        for (ranges) |record| metadata_table_manager.freeRange(alloc, record);
        alloc.free(ranges);
    }
    _ = try workflow.createTableWithRanges(svc, table, ranges);
    try svc.runRound();
}

fn replaceTableDefinitionOnService(
    svc: anytype,
    expected: metadata_table_manager.TableRecord,
    replacement: metadata_table_manager.TableRecord,
) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const current = tables_api.findTableByName(&snapshot, replacement.name) orelse return error.TableNotFound;
    if (!metadata_table_manager.tableDefinitionsEqual(current.*, expected) or replacement.table_id != expected.table_id) return error.TableGenerationChanged;
    if (extensionOwnsTableShape(&snapshot, replacement.name)) return error.ExtensionOwnedObject;

    try svc.replaceTableDefinition(expected, replacement);
    try svc.runRound();
}

fn dropTableOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsTableScopedObject(&snapshot, table_name)) return error.ExtensionOwnedObject;

    var workflow = metadata_table_workflow.TableWorkflow.init(alloc);
    defer workflow.deinit();
    _ = try workflow.dropTable(svc, table.table_id);
    try svc.runRound();
}

fn updateSchemaOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) !u32 {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsTableShape(&snapshot, table_name)) return error.ExtensionOwnedObject;

    const updated = try tables_api.applySchemaUpdateRecord(alloc, table, schema_json);
    defer metadata_table_manager.freeTable(alloc, updated);
    const version = try tables_api.schemaVersion(updated.schema_json);
    try svc.replaceTableDefinition(table.*, updated);
    try svc.runRound();
    return version;
}

fn createIndexOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8, index_json: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsIndex(&snapshot, table_name, index_name)) return error.ExtensionOwnedObject;
    const expanded_index_json = try tables_api.expandSchemaDerivedAlgebraicIndexAlloc(alloc, table_name, index_json, table.schema_json);
    defer alloc.free(expanded_index_json);

    var updated_record = table.*;
    updated_record.indexes_json = try indexes_api.addIndexToTableIndexesJson(alloc, table.indexes_json, index_name, expanded_index_json);
    defer alloc.free(updated_record.indexes_json);
    try svc.replaceTableDefinition(table.*, updated_record);
    try svc.runRound();
}

fn dropIndexOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsIndex(&snapshot, table_name, index_name)) return error.ExtensionOwnedObject;

    const indexes_json = (try indexes_api.removeIndexFromTableIndexesJson(alloc, table.indexes_json, index_name)) orelse return error.IndexNotFound;
    defer alloc.free(indexes_json);
    var updated_record = table.*;
    updated_record.indexes_json = indexes_json;
    try svc.replaceTableDefinition(table.*, updated_record);
    try svc.runRound();
}

fn putArtifactEnrichmentOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, artifact_name: []const u8, enrichment_json: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsEnrichment(&snapshot, table_name, artifact_name)) return error.ExtensionOwnedObject;

    var updated_record = table.*;
    updated_record.indexes_json = try indexes_api.addEnrichmentToTableIndexesJson(alloc, table.indexes_json, artifact_name, enrichment_json);
    defer alloc.free(updated_record.indexes_json);
    try indexes_api.validateArtifactEnrichmentsForTableIndexesJson(alloc, updated_record.indexes_json);
    try svc.replaceTableDefinition(table.*, updated_record);
    try svc.runRound();
}

fn deleteArtifactEnrichmentOnService(svc: anytype, alloc: std.mem.Allocator, table_name: []const u8, artifact_name: []const u8) !void {
    var snapshot = try svc.adminSnapshot();
    defer svc.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (extensionOwnsEnrichment(&snapshot, table_name, artifact_name)) return error.ExtensionOwnedObject;

    const indexes_json = (try indexes_api.removeEnrichmentFromTableIndexesJson(alloc, table.indexes_json, artifact_name)) orelse return error.EnrichmentNotFound;
    defer alloc.free(indexes_json);
    try indexes_api.validateArtifactEnrichmentsForTableIndexesJson(alloc, indexes_json);
    var updated_record = table.*;
    updated_record.indexes_json = indexes_json;
    try svc.replaceTableDefinition(table.*, updated_record);
    try svc.runRound();
}

fn persistRestoreTableIntent(
    service: anytype,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    location_uri: []const u8,
    connection: []const u8,
    artifact_backup_id: []const u8,
    manifest: *const backups_api.TableBackupManifest,
) !void {
    var spec = try deriveRestoreMetadataSpec(alloc, table_name, location_uri, connection, artifact_backup_id, manifest);
    defer spec.deinit(alloc);

    var snapshot = try service.adminSnapshot();
    defer service.freeAdminSnapshot(&snapshot);
    if (tables_api.findTableByName(&snapshot, table_name)) |existing| {
        if (!try metadata_table_manager.restoreIntentTopologyCompatible(alloc, existing.*, snapshot.ranges, spec.table, spec.ranges))
            return error.TableAlreadyExists;
    }

    var workflow = metadata_table_workflow.TableWorkflow.init(alloc);
    defer workflow.deinit();
    _ = try workflow.createTableWithRanges(service, spec.table, spec.ranges);
}

pub const default_metadata_mutation_retry_timeout_ns: u64 = 5 * std.time.ns_per_s;
pub const default_metadata_mutation_retry_poll_ns: u64 = 50 * std.time.ns_per_ms;

const MetadataMutationRetryPolicy = struct {
    timeout_ns: u64 = default_metadata_mutation_retry_timeout_ns,
    poll_ns: u64 = default_metadata_mutation_retry_poll_ns,
    max_attempts: ?usize = null,

    fn shouldRetry(self: @This(), err: anyerror, elapsed_ns: u64, attempt_count: usize) bool {
        if (self.max_attempts) |max_attempts| {
            if (attempt_count >= max_attempts) return false;
        }
        return shouldRetryMetadataMutation(err, elapsed_ns, self.timeout_ns);
    }
};

pub const ApiHttpServer = struct {
    const SupportedJoinRequest = distributed_join.SupportedJoinRequest;
    const SupportedJoinFilters = distributed_join.SupportedJoinFilters;
    const JoinShuffleJobPhase = distributed_join.JoinShuffleJobPhase;
    const JoinShuffleExecutionMode = distributed_join.JoinShuffleExecutionMode;
    const JoinPartitionExecutionResult = distributed_join.JoinPartitionExecutionResult;
    const RightJoinQueryResult = distributed_join.RightJoinQueryResult;
    const PlannedJoinExecution = distributed_join.PlannedJoinExecution;
    const JoinedQueryStats = distributed_join.JoinedQueryStats;
    const ParsedSupportedJoinRequest = distributed_join.ParsedSupportedJoinRequest;
    const JoinShuffleResumeState = distributed_join.JoinShuffleResumeState;
    const phaseString = distributed_join.phaseString;
    const phaseFromString = distributed_join.phaseFromString;
    const joinJobNowMillis = distributed_join.joinJobNowMillis;
    const preferredFinalizerStartIndex = distributed_join.preferredFinalizerStartIndex;
    const JoinShuffleJobState = distributed_join.JoinShuffleJobState;
    const extractJsonPathValue = distributed_join.extractJsonPathValue;
    const parseSupportedJoinRequest = distributed_join.parseSupportedJoinRequest;

    const RuntimeStatusOwnerKey = struct {
        group_id: u64,
        owner_id: u64,
    };

    const RuntimeStatusSnapshotIndex = struct {
        alloc: std.mem.Allocator,
        store_count: usize = 0,
        table_by_group: std.AutoHashMapUnmanaged(u64, u64) = .empty,
        table_id_by_name: std.StringHashMapUnmanaged(u64) = .empty,
        groups_by_table: std.AutoHashMapUnmanaged(u64, std.ArrayListUnmanaged(u64)) = .empty,
        groups_with_placements: std.AutoHashMapUnmanaged(u64, void) = .empty,
        store_owners: std.AutoHashMapUnmanaged(RuntimeStatusOwnerKey, void) = .empty,
        node_owners: std.AutoHashMapUnmanaged(RuntimeStatusOwnerKey, void) = .empty,
        reports_by_table: std.AutoHashMapUnmanaged(u64, std.ArrayListUnmanaged(*const metadata_table_manager.RuntimeGroupStatusReport)) = .empty,

        fn init(
            alloc: std.mem.Allocator,
            snapshot: *const metadata_api.AdminSnapshot,
            prefix: ?[]const u8,
        ) !RuntimeStatusSnapshotIndex {
            var index = RuntimeStatusSnapshotIndex{
                .alloc = alloc,
                .store_count = snapshot.stores.len,
            };
            errdefer index.deinit();

            var table_names = std.AutoHashMapUnmanaged(u64, []const u8).empty;
            defer table_names.deinit(alloc);
            const selected_table_count = if (prefix) |value| count: {
                var count: usize = 0;
                for (snapshot.tables) |table| {
                    if (std.mem.startsWith(u8, table.name, value)) count += 1;
                }
                break :count count;
            } else snapshot.tables.len;
            try table_names.ensureTotalCapacity(
                alloc,
                std.math.cast(u32, selected_table_count) orelse return error.TooManyRuntimeStatuses,
            );
            try index.table_id_by_name.ensureTotalCapacity(
                alloc,
                std.math.cast(u32, selected_table_count) orelse return error.TooManyRuntimeStatuses,
            );
            for (snapshot.tables) |table| {
                if (prefix) |value| {
                    if (!std.mem.startsWith(u8, table.name, value)) continue;
                }
                table_names.putAssumeCapacity(table.table_id, table.name);
                index.table_id_by_name.putAssumeCapacity(table.name, table.table_id);
            }

            const selected_range_count = if (prefix != null) count: {
                var count: usize = 0;
                for (snapshot.ranges) |range| {
                    if (table_names.contains(range.table_id)) count += 1;
                }
                break :count count;
            } else snapshot.ranges.len;
            try index.table_by_group.ensureTotalCapacity(alloc, std.math.cast(u32, selected_range_count) orelse return error.TooManyRuntimeStatuses);
            for (snapshot.ranges) |range| {
                if (!table_names.contains(range.table_id)) continue;
                index.table_by_group.putAssumeCapacity(range.group_id, range.table_id);
                const entry = try index.groups_by_table.getOrPut(alloc, range.table_id);
                if (!entry.found_existing) entry.value_ptr.* = .empty;
                try entry.value_ptr.append(alloc, range.group_id);
            }

            for (snapshot.placement_intents) |intent| {
                if (!index.table_by_group.contains(intent.record.group_id)) continue;
                try index.groups_with_placements.put(alloc, intent.record.group_id, {});
                if (intent.store_id != 0) {
                    try index.store_owners.put(alloc, .{
                        .group_id = intent.record.group_id,
                        .owner_id = intent.store_id,
                    }, {});
                }
                if (intent.record.local_node_id != 0) {
                    try index.node_owners.put(alloc, .{
                        .group_id = intent.record.group_id,
                        .owner_id = intent.record.local_node_id,
                    }, {});
                }
                for (intent.peer_node_ids) |peer_node_id| {
                    try index.node_owners.put(alloc, .{
                        .group_id = intent.record.group_id,
                        .owner_id = peer_node_id,
                    }, {});
                }
            }

            for (snapshot.stores) |*store| {
                for (store.runtime_statuses) |*report| {
                    const table_id = index.table_by_group.get(report.group_id) orelse continue;
                    if (report.table_id != 0 and report.table_id != table_id) continue;
                    if (report.table_name.len != 0) {
                        const table_name = table_names.get(table_id) orelse continue;
                        if (!std.mem.eql(u8, report.table_name, table_name)) continue;
                    }
                    if (index.groups_with_placements.contains(report.group_id) and
                        !index.store_owners.contains(.{ .group_id = report.group_id, .owner_id = store.store_id }) and
                        !index.node_owners.contains(.{ .group_id = report.group_id, .owner_id = store.node_id }))
                    {
                        continue;
                    }
                    const entry = try index.reports_by_table.getOrPut(alloc, table_id);
                    if (!entry.found_existing) entry.value_ptr.* = .empty;
                    try entry.value_ptr.append(alloc, report);
                }
            }
            return index;
        }

        fn deinit(self: *RuntimeStatusSnapshotIndex) void {
            var groups_iterator = self.groups_by_table.valueIterator();
            while (groups_iterator.next()) |groups| groups.deinit(self.alloc);
            self.groups_by_table.deinit(self.alloc);
            var iterator = self.reports_by_table.valueIterator();
            while (iterator.next()) |reports| reports.deinit(self.alloc);
            self.reports_by_table.deinit(self.alloc);
            self.table_by_group.deinit(self.alloc);
            self.table_id_by_name.deinit(self.alloc);
            self.groups_with_placements.deinit(self.alloc);
            self.store_owners.deinit(self.alloc);
            self.node_owners.deinit(self.alloc);
            self.* = undefined;
        }

        fn reportsForTable(
            self: *const RuntimeStatusSnapshotIndex,
            table_id: u64,
        ) []const *const metadata_table_manager.RuntimeGroupStatusReport {
            const reports = self.reports_by_table.get(table_id) orelse return &.{};
            return reports.items;
        }

        fn groupIdsForTable(self: *const RuntimeStatusSnapshotIndex, table_id: u64) []const u64 {
            const groups = self.groups_by_table.get(table_id) orelse return &.{};
            return groups.items;
        }

        fn tableId(self: *const RuntimeStatusSnapshotIndex, table_name: []const u8) ?u64 {
            return self.table_id_by_name.get(table_name);
        }

        fn statusAllowed(
            self: *const RuntimeStatusSnapshotIndex,
            table_name: []const u8,
            status: runtime_status.LocalTableRuntimeStatus,
            fallback_node_id: u64,
        ) bool {
            const table_id = self.table_id_by_name.get(table_name) orelse return true;
            if (self.table_by_group.get(status.group_id)) |owner_table_id| {
                if (owner_table_id != table_id) return false;
            } else if (self.groups_by_table.contains(table_id)) {
                return false;
            }
            if (!self.groups_with_placements.contains(status.group_id)) return true;
            if (status.metadata.store_id != 0 and self.store_owners.contains(.{
                .group_id = status.group_id,
                .owner_id = status.metadata.store_id,
            })) return true;
            const node_id = if (status.metadata.node_id != 0) status.metadata.node_id else fallback_node_id;
            if (node_id != 0 and self.node_owners.contains(.{
                .group_id = status.group_id,
                .owner_id = node_id,
            })) return true;
            return status.metadata.store_id == 0 and node_id == 0 and self.store_count <= 1;
        }
    };

