    pub const RequestStats = struct {
        request_count: u64 = 0,
        first_request_started_at_ns: u64 = 0,
        first_request_elapsed_ms: u64 = 0,
        query_embedding_cache: query_embedding_cache.Stats = .{},
        inference_cache_budget: cache_budget.CacheBudget.Stats = .{
            .max_bytes = 0,
            .used_bytes = 0,
            .rejected_reservations = 0,
        },
    };

    const RuntimeOwnerIds = struct {
        repair: u64 = 0,
        restore: u64 = 0,
        session_maintenance: u64 = 0,
        backup_maintenance: u64 = 0,
        index_installation: u64 = 0,
    };

    fn allocRuntimeOwnerIds(runtime: ?*db_mod.background_runtime.BackendRuntime) !RuntimeOwnerIds {
        const active = runtime orelse return .{};
        var ids: RuntimeOwnerIds = .{};
        errdefer {
            if (ids.repair != 0) active.durable_jobs.closeOwner(ids.repair);
            if (ids.restore != 0) active.durable_jobs.closeOwner(ids.restore);
            if (ids.session_maintenance != 0) active.durable_jobs.closeOwner(ids.session_maintenance);
            if (ids.backup_maintenance != 0) active.durable_jobs.closeOwner(ids.backup_maintenance);
            if (ids.index_installation != 0) active.durable_jobs.closeOwner(ids.index_installation);
        }
        ids.repair = try active.allocOwnerId();
        ids.restore = try active.allocOwnerId();
        ids.session_maintenance = try active.allocOwnerId();
        ids.backup_maintenance = try active.allocOwnerId();
        ids.index_installation = try active.allocOwnerId();
        return ids;
    }

    pub fn init(
        alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
    ) ApiHttpServer {
        const request_alloc = if (builtin.is_test)
            alloc
        else
            platform.allocator.processAllocator(std.heap.smp_allocator);
        return ApiHttpServer.initWithRequestAllocator(alloc, request_alloc, cfg, source, table_read_source, table_write_source);
    }

    pub fn haMutationPolicy(self: *const ApiHttpServer) HAMutationPolicySnapshot {
        if (self.cfg.ha_mutation_policy_source) |source| return source.snapshot();
        return .{
            .failover_safe_mutations_only = self.cfg.ha_failover_safe_mutations_only,
            .remote_apply_mutations_enabled = self.cfg.ha_remote_apply_mutations_enabled,
        };
    }

    pub fn initWithProcessRequestAllocator(
        owner_alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
    ) ApiHttpServer {
        return ApiHttpServer.initWithRequestAllocator(
            owner_alloc,
            platform.allocator.processAllocator(std.heap.smp_allocator),
            cfg,
            source,
            table_read_source,
            table_write_source,
        );
    }

    pub fn initForTestingWithRequestAllocator(
        owner_alloc: std.mem.Allocator,
        request_alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
    ) ApiHttpServer {
        std.debug.assert(builtin.is_test);
        return ApiHttpServer.initWithRequestAllocator(owner_alloc, request_alloc, cfg, source, table_read_source, table_write_source);
    }

    fn initWithRequestAllocator(
        owner_alloc: std.mem.Allocator,
        request_alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
    ) ApiHttpServer {
        const owner_ids = allocRuntimeOwnerIds(cfg.backend_runtime) catch {
            @panic("API background owner registration failed");
        };
        return initWithRequestAllocatorAndOwners(
            owner_alloc,
            request_alloc,
            cfg,
            source,
            table_read_source,
            table_write_source,
            owner_ids,
        );
    }

    fn initWithRequestAllocatorAndOwners(
        owner_alloc: std.mem.Allocator,
        request_alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
        owner_ids: RuntimeOwnerIds,
    ) ApiHttpServer {
        const effective_query_embedding_cache = effectiveQueryEmbeddingCacheConfig(cfg);
        const api_io = queryEmbeddingCacheIo(cfg);
        return .{
            .alloc = request_alloc,
            .owner_alloc = owner_alloc,
            .cfg = cfg,
            .query_admission = RequestAdmission.init(cfg.query_max_concurrent_requests),
            .write_admission = RequestAdmission.init(cfg.write_max_concurrent_requests),
            .inference_admission = RequestAdmission.init(cfg.inference_max_concurrent_requests),
            .source = source,
            .table_reads = table_read_source,
            .table_writes = table_write_source,
            .foreign_registry = cfg.foreign_registry,
            .created_at_ns = platform_time.monotonicNs(),
            .txn_sessions = blk: {
                var registry = transactions_api.SessionRegistry.initWithOptions(
                    cfg.session_store,
                    if (cfg.session_store != null and cfg.session_owner_lease_ttl_ns != null)
                        transactions_api.SessionLeaseStore.initFromDurable(cfg.session_store.?)
                    else
                        null,
                    cfg.session_owner_lease_ttl_ns,
                    cfg.session_savepoint_limit,
                    cfg.session_max_count,
                    cfg.session_max_record_bytes,
                );
                registry.durable_scope = cfg.session_store_scope;
                break :blk registry;
            },
            .join_job_store = distributed_join.JoinJobStore.init(owner_alloc, .{
                .join_job_store_path = cfg.join_job_store_path,
                .join_job_lease_ttl_ms = cfg.join_job_lease_ttl_ms,
                .join_job_retention_ms = cfg.join_job_retention_ms,
            }),
            .artifact_reprocess_job_store = artifact_reprocess_jobs.Store.init(owner_alloc, .{
                .artifact_reprocess_job_store_path = cfg.artifact_reprocess_job_store_path,
                .artifact_reprocess_job_retention_ms = cfg.artifact_reprocess_job_retention_ms,
            }),
            .repair_job_store = repair_jobs.Store.init(owner_alloc, .{
                .repair_job_store_path = cfg.repair_job_store_path,
                .repair_job_retention_ms = cfg.repair_job_retention_ms,
            }),
            .restore_job_store = if (cfg.backend_runtime) |runtime|
                if (runtime.io()) |io| restore_jobs.Store.initWithIo(owner_alloc, io) else restore_jobs.Store.init(owner_alloc)
            else
                restore_jobs.Store.init(owner_alloc),
            .repair_job_owner_id = owner_ids.repair,
            .restore_job_owner_id = .init(owner_ids.restore),
            .session_maintenance_owner_id = owner_ids.session_maintenance,
            .backup_maintenance_owner_id = owner_ids.backup_maintenance,
            .index_installation_owner_id = owner_ids.index_installation,
            .connections_cache = connections_api.Cache.init(owner_alloc),
            .local_resource_manager = resource_manager_mod.ResourceManager.init(.{}),
            .shared_resource_manager = cfg.resource_manager,
            .query_embedding_cache = query_embedding_cache.QueryEmbeddingCache.init(owner_alloc, api_io, effective_query_embedding_cache),
            .mcp_sessions = mcp.InMemorySessionStore.initWithOptions(owner_alloc, api_io, .{
                .now_ns_fn = protocolStoreNowNs,
            }),
            .a2a_tasks = a2a.InMemoryTaskStore.initWithOptions(owner_alloc, api_io, .{
                .now_ns_fn = protocolStoreNowNs,
            }),
        };
    }

    fn effectiveQueryEmbeddingCacheConfig(cfg: ApiHttpServerConfig) query_embedding_cache.Config {
        const manager = cfg.resource_manager orelse return .{};
        const policy = manager.queryEmbeddingPolicy();
        return .{
            .enabled = policy.enabled,
            .max_bytes = manager.queryEmbeddingCacheBudget().max_bytes,
            .ttl_ns = policy.ttl_ns,
            .max_inflight = policy.max_inflight,
        };
    }

    fn queryEmbeddingCacheIo(cfg: ApiHttpServerConfig) std.Io {
        if (cfg.backend_runtime) |runtime| {
            if (runtime.apiIoImpl()) |io_impl| return io_impl.io();
        }
        return std.Io.Threaded.global_single_threaded.io();
    }

    fn protocolStoreNowNs() u64 {
        return platform_time.monotonicNs();
    }

    pub fn inferenceIo(self: *const ApiHttpServer) std.Io {
        return queryEmbeddingCacheIo(self.cfg);
    }

    pub fn requestStats(self: *ApiHttpServer) RequestStats {
        const request_count = self.request_count.load(.monotonic);
        const first_request_started_at_ns = self.first_request_started_at_ns.load(.monotonic);
        return .{
            .request_count = request_count,
            .first_request_started_at_ns = first_request_started_at_ns,
            .first_request_elapsed_ms = if (first_request_started_at_ns == 0 or first_request_started_at_ns < self.created_at_ns)
                0
            else
                @intCast(@divTrunc(first_request_started_at_ns - self.created_at_ns, std.time.ns_per_ms)),
            .query_embedding_cache = self.query_embedding_cache.stats(self.inferenceCacheBudget()),
            .inference_cache_budget = self.inferenceCacheBudget().stats(),
        };
    }

    pub fn queryAdmissionStats(self: *const ApiHttpServer) RequestAdmission.Stats {
        return self.query_admission.stats();
    }

    pub fn tryAcquireQuery(self: *ApiHttpServer) bool {
        return self.query_admission.tryAcquire();
    }

    pub fn releaseQuery(self: *ApiHttpServer) void {
        self.query_admission.release();
    }

    pub fn queryOverloadedResponse(self: *ApiHttpServer) !contextual_operations.OwnedResponse {
        return try contextualRetryableTextResponse(self.alloc, 429, "query capacity exhausted");
    }

    pub fn writeAdmissionStats(self: *const ApiHttpServer) RequestAdmission.Stats {
        return self.write_admission.stats();
    }

    pub fn tryAcquireWrite(self: *ApiHttpServer) bool {
        return self.write_admission.tryAcquire();
    }

    pub fn releaseWrite(self: *ApiHttpServer) void {
        self.write_admission.release();
    }

    pub fn writeOverloadedResponse(self: *ApiHttpServer) !contextual_operations.OwnedResponse {
        return try contextualRetryableTextResponse(self.alloc, 429, "write capacity exhausted");
    }

    pub fn tryAcquireInference(self: *ApiHttpServer) bool {
        if (self.cfg.inference_request_admission_source) |source| return source.tryAcquire();
        return self.inference_admission.tryAcquire();
    }

    pub fn inferenceAdmissionStats(self: *const ApiHttpServer) RequestAdmission.Stats {
        if (self.cfg.inference_request_admission_source) |source| return source.stats();
        return self.inference_admission.stats();
    }

    pub fn releaseInference(self: *ApiHttpServer) void {
        if (self.cfg.inference_request_admission_source) |source| {
            source.release();
            return;
        }
        self.inference_admission.release();
    }

    pub fn inferenceOverloadedResponse(self: *ApiHttpServer) !contextual_operations.OwnedResponse {
        return try contextualInferenceCapacityResponse(self.alloc);
    }

    pub fn setHAInternalExecutor(self: *ApiHttpServer, executor_value: ?ha_http_operation.Executor) void {
        self.cfg.ha_internal_executor = executor_value;
    }

    pub fn configuredInferenceAPIURL(self: *const ApiHttpServer) ?[]const u8 {
        const node_config = self.cfg.node_config orelse return null;
        return node_config.inference.api_url;
    }

    pub fn currentStorageRuntimeStatus(self: *const ApiHttpServer) ?metadata_openapi.StorageRuntimeStatus {
        const maintenance = self.cfg.storage_maintenance orelse return null;
        return storageRuntimeStatus(maintenance.status());
    }

    /// Transport-neutral status operation shared by direct callers and every
    /// HTTP adapter. Ownership of nested allocations follows `alloc`.
    pub fn loadClusterStatus(self: *ApiHttpServer, alloc: std.mem.Allocator) !cluster.ClusterStatus {
        const metadata_status = try self.source.status();
        var status = try cluster.fromMetadataStatus(alloc, metadata_status);
        errdefer status.deinit(alloc);
        status.auth_enabled = self.cfg.auth_enabled;
        status.deployment_mode = self.cfg.deployment_mode;
        status.storage = self.currentStorageRuntimeStatus();
        if (self.cfg.secret_store) |secret_store| {
            _ = secret_store.refreshIfChanged() catch |err| {
                std.log.warn("secret store status refresh skipped err={}", .{err});
            };
            try cluster.applySecretStoreHealth(alloc, &status, secret_store.healthSnapshot());
        }
        if (self.cfg.remote_content) |remote_content| {
            if (remote_content.runtimeHealth()) |health| try cluster.applyRuntimeConfigHealth(alloc, &status, health);
        }
        return status;
    }

    /// Transport-neutral topology operation. It composes the shared status
    /// operation with the best available metadata snapshot and returns one
    /// typed result instead of serialized HTTP bytes.
    pub fn loadClusterTopology(self: *ApiHttpServer, alloc: std.mem.Allocator) !cluster.ClusterTopology {
        var status = try self.loadClusterStatus(alloc);
        defer status.deinit(alloc);
        var snapshot_opt = try self.source.cachedAdminSnapshot();
        if (snapshot_opt == null) snapshot_opt = try self.source.adminSnapshot();
        if (snapshot_opt) |*snapshot| {
            defer self.source.freeAdminSnapshot(snapshot);
            return try cluster.topologyFromStatusAndSnapshot(alloc, status, snapshot);
        }
        return try cluster.topologyFromStatus(alloc, status);
    }

    pub fn initWithConfig(
        alloc: std.mem.Allocator,
        cfg: ApiHttpServerConfig,
        source: StatusSource,
        table_read_source: ?table_reads.TableReadSource,
        table_write_source: ?table_writes.TableWriteSource,
    ) !ApiHttpServer {
        var effective_cfg = cfg;
        const request_alloc = if (builtin.is_test)
            alloc
        else
            platform.allocator.processAllocator(std.heap.smp_allocator);
        const owner_ids = try allocRuntimeOwnerIds(effective_cfg.backend_runtime);
        var owner_ids_transferred = false;
        errdefer if (!owner_ids_transferred) {
            if (effective_cfg.backend_runtime) |runtime| {
                if (owner_ids.repair != 0) runtime.durable_jobs.closeOwner(owner_ids.repair);
                if (owner_ids.restore != 0) runtime.durable_jobs.closeOwner(owner_ids.restore);
                if (owner_ids.session_maintenance != 0) runtime.durable_jobs.closeOwner(owner_ids.session_maintenance);
                if (owner_ids.backup_maintenance != 0) runtime.durable_jobs.closeOwner(owner_ids.backup_maintenance);
                if (owner_ids.index_installation != 0) runtime.durable_jobs.closeOwner(owner_ids.index_installation);
            }
        };
        var server = initWithRequestAllocatorAndOwners(
            alloc,
            request_alloc,
            effective_cfg,
            source,
            table_read_source,
            table_write_source,
            owner_ids,
        );
        owner_ids_transferred = true;
        errdefer server.deinit();
        if (cfg.session_store_path) |path| {
            if (cfg.session_store != null) return error.InvalidApiServerConfig;
            const opened = try alloc.create(transactions_api.OpenedSessionStore);
            errdefer alloc.destroy(opened);
            opened.* = try transactions_api.OpenedSessionStore.open(alloc, path);
            server.opened_session_store = opened;
            effective_cfg.session_store = opened.durableStore();
            server.cfg = effective_cfg;
            server.txn_sessions = transactions_api.SessionRegistry.initWithOptions(
                effective_cfg.session_store,
                opened.leaseStore().*,
                effective_cfg.session_owner_lease_ttl_ns,
                effective_cfg.session_savepoint_limit,
                effective_cfg.session_max_count,
                effective_cfg.session_max_record_bytes,
            );
            server.txn_sessions.durable_scope = effective_cfg.session_store_scope;
        }
        if (cfg.join_job_store_path orelse cfg.session_store_path) |base_path| {
            const join_job_path = if (cfg.join_job_store_path != null)
                try alloc.dupe(u8, base_path)
            else
                try std.fmt.allocPrint(alloc, "{s}.join_jobs", .{base_path});
            defer alloc.free(join_job_path);
            const opened = try alloc.create(distributed_join.OpenedJoinJobStore);
            errdefer alloc.destroy(opened);
            opened.* = try distributed_join.OpenedJoinJobStore.open(alloc, join_job_path);
            server.join_job_store.opened_join_job_store = opened;
        }
        if (cfg.artifact_reprocess_job_store_path orelse cfg.session_store_path) |base_path| {
            const job_path = if (cfg.artifact_reprocess_job_store_path != null)
                try alloc.dupe(u8, base_path)
            else
                try std.fmt.allocPrint(alloc, "{s}.artifact_reprocess_jobs", .{base_path});
            defer alloc.free(job_path);
            const opened = try alloc.create(artifact_reprocess_jobs.OpenedStore);
            errdefer alloc.destroy(opened);
            opened.* = try artifact_reprocess_jobs.OpenedStore.open(alloc, job_path);
            errdefer opened.deinit();
            try server.artifact_reprocess_job_store.attachOpenedStore(opened);
        }
        if (cfg.repair_job_store_path orelse cfg.session_store_path) |base_path| {
            const job_path = if (cfg.repair_job_store_path != null)
                try alloc.dupe(u8, base_path)
            else
                try std.fmt.allocPrint(alloc, "{s}.repair_jobs", .{base_path});
            defer alloc.free(job_path);
            const opened = try alloc.create(repair_jobs.OpenedStore);
            errdefer alloc.destroy(opened);
            opened.* = try repair_jobs.OpenedStore.open(alloc, job_path);
            errdefer opened.deinit();
            try server.repair_job_store.attachOpenedStore(opened);
        }
        if (cfg.restore_job_store) |store| {
            try server.restore_job_store.attachRuntime(store);
        } else if (cfg.restore_job_store_path orelse cfg.session_store_path) |base_path| {
            const job_path = if (cfg.restore_job_store_path != null)
                try alloc.dupe(u8, base_path)
            else
                try std.fmt.allocPrint(alloc, "{s}.restore_jobs", .{base_path});
            defer alloc.free(job_path);
            const opened = try alloc.create(restore_jobs.OpenedStore);
            errdefer alloc.destroy(opened);
            opened.* = try restore_jobs.OpenedStore.open(alloc, job_path);
            errdefer opened.deinit();
            try server.restore_job_store.attach(opened);
        }
        return server;
    }

    pub fn setForeignRegistry(self: *ApiHttpServer, registry: *const foreign_mod.Registry) void {
        self.foreign_registry = registry;
        self.cfg.foreign_registry = registry;
    }

    fn ensureForeignRegistry(self: *ApiHttpServer) !*const foreign_mod.Registry {
        if (self.foreign_registry) |registry| return registry;
        const registry = try self.owner_alloc.create(foreign_mod.Registry);
        errdefer self.owner_alloc.destroy(registry);
        registry.* = .{};
        errdefer registry.deinit(self.owner_alloc);
        try foreign_mod.registerDefaultPostgresExecutor(self.owner_alloc, registry);
        self.owned_foreign_registry = registry;
        self.foreign_registry = registry;
        self.cfg.foreign_registry = registry;
        return registry;
    }

    pub fn deinit(self: *ApiHttpServer) void {
        self.restore_jobs_closing.store(true, .release);
        self.signalRestoreRetryWakeup();
        self.backup_maintenance_closing.store(true, .release);
        self.index_installation_closing.store(true, .release);
        if (self.cfg.backend_runtime) |runtime| {
            if (self.repair_job_owner_id != 0) runtime.durable_jobs.closeOwner(self.repair_job_owner_id);
            const restore_owner_id = self.restore_job_owner_id.load(.acquire);
            if (restore_owner_id != 0) runtime.durable_jobs.closeOwner(restore_owner_id);
            if (self.session_maintenance_owner_id != 0) runtime.durable_jobs.closeOwner(self.session_maintenance_owner_id);
            if (self.backup_maintenance_owner_id != 0) runtime.durable_jobs.closeOwner(self.backup_maintenance_owner_id);
            if (self.index_installation_owner_id != 0) runtime.durable_jobs.closeOwner(self.index_installation_owner_id);
        }
        platform_sync.lockYielding(&self.index_installation_mutex);
        for (self.index_installation_queue.items) |*entry| entry.deinit();
        self.index_installation_queue.deinit(std.heap.page_allocator);
        self.index_installation_mutex.unlock();
        platform_sync.lockYielding(&self.backup_maintenance_mutex);
        self.backup_maintenance_queue.deinit(self.owner_alloc);
        self.backup_maintenance_mutex.unlock();
        self.mcp_sessions.deinit(self.owner_alloc);
        self.a2a_tasks.deinit(self.owner_alloc);
        self.txn_sessions.deinit(self.alloc);
        if (self.opened_session_store) |opened| {
            opened.deinit();
            self.owner_alloc.destroy(opened);
        }
        self.join_job_store.deinit();
        self.artifact_reprocess_job_store.deinit();
        self.repair_job_store.deinit();
        self.restore_job_store.deinit();
        self.scheduled_restore_jobs.deinit(self.alloc);
        if (self.owned_foreign_registry) |registry| {
            registry.deinit(self.owner_alloc);
            self.owner_alloc.destroy(registry);
        }
        self.connections_cache.deinit();
        self.query_embedding_cache.deinit(self.inferenceCacheBudget());
        self.local_resource_manager.deinit(self.owner_alloc);
        self.* = undefined;
    }

    pub fn attachRestoreJobRuntimeStore(self: *ApiHttpServer, store: *backend_erased.Store) !void {
        try self.restore_job_store.attachRuntime(store);
    }

    pub fn attachReplicatedRestoreJobStore(self: *ApiHttpServer, persistence: restore_jobs.ReplicatedPersistence) !void {
        try self.restore_job_store.attachReplicated(persistence);
    }

    /// Rotates worker ownership and rebuilds the runnable queue from replicated
    /// state at a metadata Raft leadership boundary.
    pub fn prepareRestoreLeadership(self: *ApiHttpServer, leadership_term: u64) !void {
        platform_sync.lockYielding(&self.restore_transition_mutex);
        defer self.restore_transition_mutex.unlock();
        const runtime = self.cfg.backend_runtime orelse return error.AsyncRestoreUnavailable;

        // Stop admission before waiting for the current dispatcher. Completion
        // callbacks only request a later pass while paused, so draining the old
        // owner cannot wait on its own dispatch mutex.
        self.restore_dispatch_paused.store(true, .release);
        self.signalRestoreRetryWakeup();
        platform_sync.lockYielding(&self.restore_dispatch_mutex);
        const transition_result = self.prepareRestoreLeadershipLocked(runtime, leadership_term);
        self.restore_dispatch_mutex.unlock();
        try transition_result;
        if (runtime.threaded_jobs != null) try self.resumeRestoreJobsOnce();
    }

    fn prepareRestoreLeadershipLocked(self: *ApiHttpServer, runtime: *db_mod.background_runtime.BackendRuntime, leadership_term: u64) !void {
        self.restore_leadership_term.store(0, .release);
        const previous_owner_id = self.restore_job_owner_id.swap(0, .acq_rel);
        if (previous_owner_id != 0) runtime.durable_jobs.closeOwner(previous_owner_id);
        platform_sync.lockYielding(&self.restore_schedule_mutex);
        self.scheduled_restore_jobs.clearRetainingCapacity();
        self.restore_schedule_mutex.unlock();
        self.restore_jobs_resumed.store(false, .release);
        try self.restore_job_store.prepareReplicatedLeadership(self.alloc);
        self.restore_job_owner_id.store(try runtime.allocOwnerId(), .release);
        self.restore_leadership_term.store(leadership_term, .release);
        self.restore_dispatch_paused.store(false, .release);
        self.restore_dispatch_requested.store(true, .release);
    }

    pub fn attachRestoreJobStorePath(self: *ApiHttpServer, path: []const u8) !void {
        const opened = try self.alloc.create(restore_jobs.OpenedStore);
        errdefer self.alloc.destroy(opened);
        opened.* = try restore_jobs.OpenedStore.open(self.alloc, path);
        errdefer opened.deinit();
        try self.restore_job_store.attach(opened);
    }

