    fn publicQueryOperationErrorResponse(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        err: anyerror,
    ) !contextual_operations.OwnedResponse {
        return switch (err) {
            error.InvalidQueryRequest => if (db_mod.peekLastSortRejectionDiagnostic() != null)
                try contextualUnsupportedExactSortResponse(self.alloc)
            else
                try contextual_operations.textAlloc(self.alloc, 400, "invalid query request"),
            error.InvalidFilterQueryRequest => try contextualPublicFilterQueryErrorResponseForBody(self.alloc, body, "filter_query", .invalid),
            error.InvalidExclusionQueryRequest => try contextualPublicFilterQueryErrorResponseForBody(self.alloc, body, "exclusion_query", .invalid),
            error.UnsupportedFilterQueryRequest => try contextualPublicFilterQueryErrorResponseForBody(self.alloc, body, "filter_query", .unsupported),
            error.UnsupportedExclusionQueryRequest => try contextualPublicFilterQueryErrorResponseForBody(self.alloc, body, "exclusion_query", .unsupported),
            error.UnsupportedExactSort => try contextualUnsupportedExactSortResponse(self.alloc),
            error.UnsupportedQueryRequest => if (queryBodyHasSortPageControls(self.alloc, body))
                try contextualUnsupportedExactSortResponse(self.alloc)
            else
                try contextual_operations.textAlloc(self.alloc, 422, "unsupported query request"),
            error.IdentityReadGenerationChanged => try contextualRetryableTextResponse(self.alloc, 409, "identity read generation changed"),
            error.HierarchyCursorStale => try contextualHierarchyCursorStaleResponse(self.alloc),
            error.QueryCandidateBudgetExceeded => try contextualQueryCandidateBudgetExceededResponse(self.alloc),
            error.QueryEmbeddingInputTooLarge => try contextual_operations.textAlloc(self.alloc, 413, "query embedding input too large"),
            error.QueryEmbeddingOverloaded => try contextualRetryableTextResponse(self.alloc, 429, "query embedding overloaded"),
            error.EmbedRateLimited => try contextualRetryableTextResponse(self.alloc, 429, "query embedding rate limited"),
            error.EmbedTransientFailure => try contextualQueryTemporarilyUnavailableResponse(self.alloc, .query_embedding_temporarily_unavailable),
            error.EmbedUpstreamFailure => try contextual_operations.textAlloc(self.alloc, 502, "query embedding provider failed"),
            error.Timeout => try contextual_operations.textAlloc(self.alloc, 504, "query timed out"),
            error.Cancelled => try contextual_operations.textAlloc(self.alloc, 499, "client closed request"),
            error.NotFound, error.TableNotFound => try contextual_operations.textAlloc(self.alloc, 404, "not found"),
            error.ModelNotFound => contextual_operations.json(try self.alloc.dupe(u8, "{\"error\":\"MODEL_NOT_FOUND\",\"message\":\"model not found\"}"), false),
            error.DocIdentityNamespaceMismatch => try contextualQueryTemporarilyUnavailableResponse(self.alloc, .doc_identity_unavailable),
            error.IndexRebuilding => try contextualQueryTemporarilyUnavailableResponse(self.alloc, .index_rebuilding),
            error.HAReadRequiresPrimary, error.ReadRequiresPrimary => try contextualQueryTemporarilyUnavailableResponse(self.alloc, .read_requires_primary),
            error.HAReadWaitForApply, error.HAReadWaitForMetadata, error.ReadUnavailable => try contextualQueryTemporarilyUnavailableResponse(self.alloc, .standby_read_unavailable),
            error.PersistentDescriptorAdmissionExhausted, error.StorageReadTemporarilyUnavailable => try contextualQueryTemporarilyUnavailableResponse(self.alloc, .storage_read_temporarily_unavailable),
            error.InvalidManifest,
            error.InvalidTableFile,
            error.TableBlockChecksumMismatch,
            error.CorruptInput,
            error.UnsupportedVersion,
            error.Corrupted,
            => contextual_operations.jsonWithStatus(500, try public_table_http.tableStorageUnreadableBody(self.alloc, err), false),
            else => {
                std.log.err("public table query execution failed table={s} err={}", .{ table_name, err });
                return try contextual_operations.textAlloc(self.alloc, 500, "query failed");
            },
        };
    }

    pub fn handlePublicTableQuery(self: *ApiHttpServer, table_name: []const u8, body: []const u8, authenticated_identity: ?AuthenticatedIdentity) !contextual_operations.OwnedResponse {
        return try self.handlePublicTableQueryWithContentTypeCancellation(table_name, body, null, authenticated_identity, null);
    }

    fn handlePublicTableQueryWithCancellation(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        cancellation: ?*const http_common.RequestCancellation,
    ) !contextual_operations.OwnedResponse {
        const row_filter_json = try resolveEffectiveRowFilterJson(self.alloc, authenticated_identity, table_name);
        defer if (row_filter_json) |value| self.alloc.free(value);

        const source = self.table_reads orelse return try contextual_operations.textAlloc(self.alloc, 404, "not found");
        db_mod.resetLastSortRejectionDiagnostic();
        const response_body = self.executePublicTableQueryDispatchWithReadinessRetry(
            self.alloc,
            source,
            table_name,
            body,
            row_filter_json,
            authenticated_identity,
            if (cancellation) |value| value.token() else null,
        ) catch |err| return try self.publicQueryOperationErrorResponse(table_name, body, err);
        return contextual_operations.json(response_body, false);
    }

    fn handlePublicTableMultiQuery(
        self: *ApiHttpServer,
        route_table_name: ?[]const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !contextual_operations.OwnedResponse {
        return try self.handlePublicTableMultiQueryWithCancellation(route_table_name, body, authenticated_identity, null);
    }

    fn handlePublicTableMultiQueryWithCancellation(
        self: *ApiHttpServer,
        route_table_name: ?[]const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        cancellation: ?*const http_common.RequestCancellation,
    ) !contextual_operations.OwnedResponse {
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const arena = arena_impl.allocator();

        var out: std.Io.Writer.Allocating = .init(self.alloc);
        defer out.deinit();
        try out.writer.writeAll("{\"responses\":[");
        var emitted: usize = 0;

        var lines = std.mem.splitScalar(u8, body, '\n');
        while (lines.next()) |raw_line| {
            if (cancellation) |value| {
                if (value.isCancelled()) {
                    return try self.publicQueryOperationErrorResponse(
                        route_table_name orelse "",
                        raw_line,
                        error.Cancelled,
                    );
                }
            }
            const line = std.mem.trim(u8, raw_line, " \t\r");
            if (line.len == 0) continue;

            const table_name = if (route_table_name) |name| name else blk: {
                var parsed_table = parseGlobalQueryTable(arena, line) catch {
                    return try contextual_operations.textAlloc(self.alloc, 400, "invalid query request");
                };
                defer parsed_table.deinit();
                if (parsed_table.table_name.len == 0) {
                    return try contextual_operations.textAlloc(self.alloc, 400, "invalid query request");
                }
                break :blk parsed_table.table_name;
            };

            const row_filter_json = try resolveEffectiveRowFilterJson(self.alloc, authenticated_identity, table_name);
            defer if (row_filter_json) |value| self.alloc.free(value);

            const source = self.table_reads orelse return try contextual_operations.textAlloc(self.alloc, 404, "not found");
            db_mod.resetLastSortRejectionDiagnostic();
            const response_body = self.executePublicTableQueryDispatchWithReadinessRetry(
                self.alloc,
                source,
                table_name,
                line,
                row_filter_json,
                authenticated_identity,
                if (cancellation) |value| value.token() else null,
            ) catch |err| return try self.publicQueryOperationErrorResponse(table_name, line, err);
            defer self.alloc.free(response_body);

            var parsed = std.json.parseFromSlice(std.json.Value, arena, response_body, .{
                .allocate = .alloc_always,
            }) catch return try contextual_operations.textAlloc(self.alloc, 500, "query failed");
            defer parsed.deinit();
            const object = switch (parsed.value) {
                .object => |object| object,
                else => return try contextual_operations.textAlloc(self.alloc, 500, "query failed"),
            };
            const responses_value = object.get("responses") orelse return try contextual_operations.textAlloc(self.alloc, 500, "query failed");
            const responses = switch (responses_value) {
                .array => |array| array.items,
                else => return try contextual_operations.textAlloc(self.alloc, 500, "query failed"),
            };
            for (responses) |response_value| {
                if (emitted > 0) try out.writer.writeByte(',');
                try std.json.Stringify.value(response_value, .{}, &out.writer);
                emitted += 1;
            }
        }

        if (emitted == 0) return try contextual_operations.textAlloc(self.alloc, 400, "invalid query request");
        try out.writer.writeAll("]}");
        return contextual_operations.json(try self.alloc.dupe(u8, out.written()), false);
    }

    const PublicRepairListRequest = struct {
        target: []const u8 = "artifact",
        kind: ?db_mod.types.ArtifactRepairKind = null,
        index: ?[]const u8 = null,
        cursor: ?[]const u8 = null,
        limit: ?u32 = null,
    };

    pub fn handlePublicListArtifactRepairIssues(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !public_table_http.OwnedResponse {
        const source = self.table_writes orelse return try publicOperationTextResponse(self.alloc, 405, "method not allowed");
        var parsed = std.json.parseFromSlice(PublicRepairListRequest, self.alloc, if (body.len > 0) body else "{}", .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 400, "invalid repair list request");
        };
        defer parsed.deinit();
        const target = std.meta.stringToEnum(db_mod.types.RepairTarget, parsed.value.target) orelse return try publicOperationTextResponse(self.alloc, 400, "invalid repair target");
        const raw_limit: u32 = parsed.value.limit orelse 50;
        if (raw_limit == 0) return try publicOperationTextResponse(self.alloc, 400, "invalid limit");
        const limit: u32 = @min(raw_limit, 500);
        var result = (source.listArtifactRepairIssues(self.alloc, table_name, .{
            .target = target,
            .artifact_kind = parsed.value.kind,
            .index_name = parsed.value.index,
            .limit = limit,
            .cursor = parsed.value.cursor,
        }) catch |err| switch (err) {
            error.InvalidArgument => return try publicOperationTextResponse(self.alloc, 400, "invalid cursor"),
            else => {
                std.log.err("artifact repair issue list failed table={s} err={}", .{ table_name, err });
                return try publicOperationTextResponse(self.alloc, 500, "artifact repair issue list failed");
            },
        }) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);

        const response_body = try std.json.Stringify.valueAlloc(self.alloc, .{
            .table = table_name,
            .target = @tagName(target),
            .limit = limit,
            .scanned = result.scanned,
            .groups_scanned = result.groups_scanned,
            .has_more = result.has_more,
            .next_cursor = result.next_cursor,
            .issues = result.issues,
        }, .{ .emit_null_optional_fields = false });
        return .{ .status = 200, .body = response_body, .json = true };
    }

    const PublicRepairRunRequest = struct {
        target: []const u8 = "artifact",
        kind: ?db_mod.types.ArtifactRepairKind = null,
        index: ?[]const u8 = null,
        cursor: ?[]const u8 = null,
        limit: ?u32 = null,
        force: bool = false,
        control: ?[]const u8 = null,
        repair_id: ?[]const u8 = null,
    };

    pub fn handlePublicRunTableRepair(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !public_table_http.OwnedResponse {
        const source = self.table_writes orelse return try publicOperationTextResponse(self.alloc, 405, "method not allowed");
        var parsed = std.json.parseFromSlice(PublicRepairRunRequest, self.alloc, if (body.len > 0) body else "{}", .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 400, "invalid repair request");
        };
        defer parsed.deinit();
        const body_target = std.meta.stringToEnum(db_mod.types.RepairTarget, parsed.value.target) orelse return try publicOperationTextResponse(self.alloc, 400, "invalid repair target");
        const target = body_target;
        const raw_limit = parsed.value.limit orelse 100;
        if (raw_limit == 0) return try publicOperationTextResponse(self.alloc, 400, "invalid limit");
        const limit: u32 = @min(raw_limit, 1000);
        const control = if (parsed.value.control) |raw|
            std.meta.stringToEnum(db_mod.types.IndexRepairControl, raw) orelse return try publicOperationTextResponse(self.alloc, 400, "invalid repair control")
        else
            null;
        const repair_id = if (parsed.value.repair_id) |raw|
            std.fmt.parseInt(u128, raw, 10) catch return try publicOperationTextResponse(self.alloc, 400, "invalid repair id")
        else
            null;
        var result = (source.repairArtifactIssues(self.alloc, table_name, .{
            .target = target,
            .artifact_kind = parsed.value.kind,
            .index_name = parsed.value.index,
            .limit = limit,
            .cursor = parsed.value.cursor,
            .force = parsed.value.force,
            .control = control,
            .repair_id = repair_id,
        }) catch |err| switch (err) {
            error.InvalidArgument => return try publicOperationTextResponse(self.alloc, 400, "invalid repair request"),
            error.StaleIndexRepairControl => return try publicOperationTextResponse(self.alloc, 409, "repair changed; refresh and retry"),
            else => {
                std.log.err("table repair failed table={s} err={}", .{ table_name, err });
                return try publicOperationTextResponse(self.alloc, 500, "table repair failed");
            },
        }) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);
        const response_body = try std.json.Stringify.valueAlloc(self.alloc, .{
            .table = table_name,
            .target = @tagName(target),
            .limit = limit,
            .result = result,
        }, .{ .emit_null_optional_fields = false });
        return .{ .status = 200, .body = response_body, .json = true };
    }

    pub fn handlePublicStartTableRepairJob(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !public_table_http.OwnedResponse {
        if (self.table_writes == null) return try publicOperationTextResponse(self.alloc, 405, "method not allowed");
        var parsed = std.json.parseFromSlice(repair_jobs.StartRequest, self.alloc, if (body.len > 0) body else "{}", .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 400, "invalid repair job request");
        };
        defer parsed.deinit();
        if (std.meta.stringToEnum(db_mod.types.RepairTarget, parsed.value.target) == null) return try publicOperationTextResponse(self.alloc, 400, "invalid repair target");
        if (parsed.value.limit == 0) return try publicOperationTextResponse(self.alloc, 400, "invalid limit");

        const encoded = try self.repair_job_store.startJob(self.alloc, table_name, .{
            .target = parsed.value.target,
            .kind = parsed.value.kind,
            .index = parsed.value.index,
            .cursor = parsed.value.cursor,
            .limit = @min(parsed.value.limit, 1000),
            .force = parsed.value.force,
            .advance = parsed.value.advance,
        });
        defer self.alloc.free(encoded);
        if (parsed.value.advance) {
            var parsed_state = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
                return try publicOperationTextResponse(self.alloc, 500, "repair job failed");
            };
            defer parsed_state.deinit();
            return try self.advanceTableRepairJobState(table_name, parsed_state.value);
        }
        return try publicOperationJsonResponse(self.alloc, 202, encoded);
    }

    pub fn handlePublicTableRepairJob(self: *ApiHttpServer, table_name: []const u8, encoded_job_id: []const u8) !public_table_http.OwnedResponse {
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try publicOperationTextResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.repair_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "repair job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name)) return try publicOperationTextResponse(self.alloc, 404, "not found");
        return try publicOperationJsonResponse(self.alloc, 200, encoded);
    }

    pub fn handlePublicAdvanceTableRepairJob(self: *ApiHttpServer, table_name: []const u8, encoded_job_id: []const u8) !public_table_http.OwnedResponse {
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try publicOperationTextResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.repair_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "repair job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name)) return try publicOperationTextResponse(self.alloc, 404, "not found");
        return try self.advanceTableRepairJobState(table_name, parsed.value);
    }

    pub fn handlePublicCancelTableRepairJob(self: *ApiHttpServer, table_name: []const u8, encoded_job_id: []const u8) !public_table_http.OwnedResponse {
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try publicOperationTextResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.repair_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "repair job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name)) return try publicOperationTextResponse(self.alloc, 404, "not found");
        const cancelled = try self.repair_job_store.requestCancel(self.alloc, parsed.value);
        defer self.alloc.free(cancelled);
        var parsed_cancelled = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, cancelled, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "invalid repair job state");
        };
        defer parsed_cancelled.deinit();
        if (repair_jobs.requiresDurableCancel(parsed_cancelled.value) and
            std.mem.eql(u8, parsed_cancelled.value.phase, repair_jobs.phaseString(.queued)))
        {
            return try self.advanceTableRepairJobState(table_name, parsed_cancelled.value);
        }
        return try publicOperationJsonResponse(self.alloc, if (repair_jobs.isTerminalPhase(parsed_cancelled.value.phase)) 200 else 202, cancelled);
    }

    fn advanceTableRepairJobState(self: *ApiHttpServer, table_name: []const u8, state: repair_jobs.JobState) !public_table_http.OwnedResponse {
        if (repair_jobs.isTerminalPhase(state.phase)) {
            const encoded = try repair_jobs.encodeState(self.alloc, state);
            defer self.alloc.free(encoded);
            return try publicOperationJsonResponse(self.alloc, 200, encoded);
        }

        const begin = try self.repair_job_store.beginAdvance(self.alloc, state);
        defer self.alloc.free(begin.encoded);
        var parsed_running = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, begin.encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "invalid repair job state");
        };
        defer parsed_running.deinit();
        const running_state = parsed_running.value;
        if (!begin.started) {
            return try publicOperationJsonResponse(self.alloc, if (repair_jobs.isTerminalPhase(running_state.phase)) 200 else 202, begin.encoded);
        }

        const updated = if (try self.submitTableRepairJobPass(table_name, begin.encoded, running_state.job_id)) |submitted|
            submitted
        else
            try self.runTableRepairJobPass(table_name, running_state);
        defer self.alloc.free(updated);
        var parsed_updated = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, updated, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "invalid repair job state");
        };
        defer parsed_updated.deinit();
        return try publicOperationJsonResponse(self.alloc, if (repair_jobs.isTerminalPhase(parsed_updated.value.phase)) 200 else 202, updated);
    }

    const TableRepairJobPassWork = struct {
        server: *ApiHttpServer,
        table_name: []u8,
        running_encoded: []u8,

        fn run(ptr: *anyopaque) !void {
            const work: *TableRepairJobPassWork = @ptrCast(@alignCast(ptr));
            var parsed = try std.json.parseFromSlice(repair_jobs.JobState, work.server.alloc, work.running_encoded, .{ .ignore_unknown_fields = true });
            defer parsed.deinit();
            const heartbeat = work.server.submitTableRepairJobHeartbeat(parsed.value.job_id, parsed.value.attempt_id) catch null;
            defer if (heartbeat) |hb| hb.stop.store(true, .release);
            const updated = work.server.runTableRepairJobPass(work.table_name, parsed.value) catch |err| {
                // An unexpected worker failure is operational, not evidence
                // that the repair request is invalid. Return it to the durable
                // backoff queue so cancellation and operator work remain
                // restart-safe.
                const recovered = work.server.repair_job_store.recordRetryableFailure(
                    work.server.alloc,
                    parsed.value,
                    @errorName(err),
                ) catch |recovery_err| {
                    std.log.err("failed to recover table repair job state table={s} job_id={d} worker_err={s} recovery_err={s}", .{
                        work.table_name,
                        parsed.value.job_id,
                        @errorName(err),
                        @errorName(recovery_err),
                    });
                    return recovery_err;
                };
                work.server.alloc.free(recovered);
                return err;
            };
            defer work.server.alloc.free(updated);
            work.server.continueDurableRepairCancellation(work.table_name, updated) catch |err| {
                std.log.warn("failed to continue durable table repair cancellation table={s} err={s}", .{ work.table_name, @errorName(err) });
            };
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *TableRepairJobPassWork = @ptrCast(@alignCast(ptr));
            work.server.alloc.free(work.running_encoded);
            work.server.alloc.free(work.table_name);
            work.server.alloc.destroy(work);
        }
    };

    const TableRepairJobHeartbeatWork = struct {
        server: *ApiHttpServer,
        job_id: u64,
        attempt_id: u64,
        stop: std.atomic.Value(bool) = .init(false),

        const interval_ns: u64 = 30 * std.time.ns_per_s;
        const poll_ns: u64 = 100 * std.time.ns_per_ms;

        fn run(ptr: *anyopaque) !void {
            const self: *TableRepairJobHeartbeatWork = @ptrCast(@alignCast(ptr));
            const runtime = self.server.cfg.backend_runtime orelse return;
            const io_impl = runtime.apiIoImpl() orelse runtime.io_impl orelse return;
            var elapsed_ns: u64 = 0;
            while (!self.stop.load(.acquire)) {
                io_impl.io().sleep(std.Io.Duration.fromNanoseconds(@intCast(poll_ns)), .awake) catch {};
                if (self.stop.load(.acquire)) break;
                elapsed_ns +|= poll_ns;
                if (elapsed_ns < interval_ns) continue;
                elapsed_ns = 0;
                self.server.repair_job_store.heartbeatRunning(self.server.alloc, self.job_id, self.attempt_id) catch |err| {
                    std.log.warn("failed to heartbeat table repair job job_id={d} attempt_id={d} err={s}", .{
                        self.job_id,
                        self.attempt_id,
                        @errorName(err),
                    });
                };
            }
        }

        fn deinit(ptr: *anyopaque) void {
            const self: *TableRepairJobHeartbeatWork = @ptrCast(@alignCast(ptr));
            self.server.alloc.destroy(self);
        }
    };

    const TableRepairCancelProbe = struct {
        server: *ApiHttpServer,
        job_id: u64,
        attempt_id: u64,
        cached_requested: std.atomic.Value(bool) = .init(false),
        last_check_ns: std.atomic.Value(u64) = .init(0),

        const check_interval_ns: u64 = 100 * std.time.ns_per_ms;

        fn check(ptr: *anyopaque) bool {
            const self: *TableRepairCancelProbe = @ptrCast(@alignCast(ptr));
            if (self.cached_requested.load(.acquire)) return true;
            const now_ns = platform_time.monotonicNs();
            const last_ns = self.last_check_ns.load(.acquire);
            if (last_ns != 0 and now_ns -| last_ns < check_interval_ns) return false;
            self.last_check_ns.store(now_ns, .release);

            const encoded = self.server.repair_job_store.loadJobAlloc(self.server.alloc, self.job_id) catch return false;
            defer if (encoded) |buf| self.server.alloc.free(buf);
            const body = encoded orelse {
                self.cached_requested.store(true, .release);
                return true;
            };
            var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.server.alloc, body, .{ .ignore_unknown_fields = true }) catch return false;
            defer parsed.deinit();
            const state = parsed.value;
            const requested = state.cancel_requested or
                repair_jobs.isTerminalPhase(state.phase) or
                state.attempt_id != self.attempt_id;
            if (requested) self.cached_requested.store(true, .release);
            return requested;
        }
    };

    fn submitTableRepairJobHeartbeat(self: *ApiHttpServer, job_id: u64, attempt_id: u64) !?*TableRepairJobHeartbeatWork {
        const runtime = self.cfg.backend_runtime orelse return null;
        if (runtime.threaded_jobs == null) return null;
        if (runtime.apiIoImpl() == null and runtime.io_impl == null) return null;
        if (self.repair_job_owner_id == 0) return null;

        const heartbeat = try self.alloc.create(TableRepairJobHeartbeatWork);
        heartbeat.* = .{
            .server = self,
            .job_id = job_id,
            .attempt_id = attempt_id,
        };
        runtime.durable_jobs.submit(.{
            .owner_id = self.repair_job_owner_id,
            .class = .maintenance,
            .ptr = heartbeat,
            .run = TableRepairJobHeartbeatWork.run,
            .deinit = TableRepairJobHeartbeatWork.deinit,
        }) catch |err| {
            self.alloc.destroy(heartbeat);
            return err;
        };
        return heartbeat;
    }

    fn submitTableRepairJobPass(self: *ApiHttpServer, table_name: []const u8, running_encoded: []const u8, job_id: u64) !?[]u8 {
        const runtime = self.cfg.backend_runtime orelse return null;
        if (runtime.threaded_jobs == null) return null;
        if (self.repair_job_owner_id == 0) return null;

        var work_consumed = false;
        const owned_table_name = try self.alloc.dupe(u8, table_name);
        errdefer if (!work_consumed) self.alloc.free(owned_table_name);
        const owned_running_encoded = try self.alloc.dupe(u8, running_encoded);
        errdefer if (!work_consumed) self.alloc.free(owned_running_encoded);
        const work = try self.alloc.create(TableRepairJobPassWork);
        errdefer if (!work_consumed) self.alloc.destroy(work);
        work.* = .{
            .server = self,
            .table_name = owned_table_name,
            .running_encoded = owned_running_encoded,
        };

        runtime.durable_jobs.submit(.{
            .owner_id = self.repair_job_owner_id,
            .class = .maintenance,
            .ptr = work,
            .run = TableRepairJobPassWork.run,
            .deinit = TableRepairJobPassWork.deinit,
        }) catch |err| {
            TableRepairJobPassWork.deinit(work);
            work_consumed = true;
            var parsed = try std.json.parseFromSlice(repair_jobs.JobState, self.alloc, running_encoded, .{ .ignore_unknown_fields = true });
            defer parsed.deinit();
            const queued = try self.repair_job_store.recordRetryableFailure(self.alloc, parsed.value, @errorName(err));
            defer self.alloc.free(queued);
            if (err == error.BackgroundOwnerClosing or err == error.BackgroundOwnerClosed) {
                std.log.warn("table repair job submission deferred during shutdown table={s} job_id={d}", .{ table_name, job_id });
            } else {
                std.log.warn("table repair job submission deferred table={s} job_id={d} err={}", .{ table_name, job_id, err });
            }
            return try self.repair_job_store.loadJobAlloc(self.alloc, job_id) orelse try self.alloc.dupe(u8, queued);
        };
        work_consumed = true;

        return try self.repair_job_store.loadJobAlloc(self.alloc, job_id) orelse try self.alloc.dupe(u8, running_encoded);
    }

    fn continueDurableRepairCancellation(self: *ApiHttpServer, table_name: []const u8, encoded: []const u8) !void {
        var parsed = try std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        if (!repair_jobs.requiresDurableCancel(parsed.value) or
            !std.mem.eql(u8, parsed.value.phase, repair_jobs.phaseString(.queued))) return;

        const begin = try self.repair_job_store.beginAdvance(self.alloc, parsed.value);
        defer self.alloc.free(begin.encoded);
        if (!begin.started) return;
        var running = try std.json.parseFromSlice(repair_jobs.JobState, self.alloc, begin.encoded, .{ .ignore_unknown_fields = true });
        defer running.deinit();
        if (try self.submitTableRepairJobPass(table_name, begin.encoded, running.value.job_id)) |submitted| {
            self.alloc.free(submitted);
        } else {
            const updated = try self.runTableRepairJobPass(table_name, running.value);
            self.alloc.free(updated);
        }
    }

    fn runTableRepairJobPass(self: *ApiHttpServer, table_name: []const u8, running_state: repair_jobs.JobState) ![]u8 {
        const source = self.table_writes orelse {
            return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
        };
        const target = std.meta.stringToEnum(db_mod.types.RepairTarget, running_state.target) orelse {
            return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "invalid repair target");
        };
        if (repair_jobs.requiresDurableCancel(running_state)) {
            var cancel_result = (source.repairArtifactIssuesControlled(self.alloc, table_name, .{
                .target = .index,
                .index_name = running_state.index,
                .limit = running_state.limit,
                .cursor = running_state.cursor,
                .control = .pause_automatic,
            }, .{}) catch |err| switch (err) {
                error.InvalidArgument, error.NotFound => {
                    return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                },
                else => {
                    std.log.warn("durable table repair cancellation deferred table={s} job_id={d} err={s}", .{ table_name, running_state.job_id, @errorName(err) });
                    return try self.repair_job_store.recordRetryableFailure(self.alloc, running_state, @errorName(err));
                },
            }) orelse {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
            };
            defer cancel_result.deinit(self.alloc);
            return try self.repair_job_store.recordDurableCancelPass(self.alloc, running_state, cancel_result);
        }
        var cancel_probe = TableRepairCancelProbe{
            .server = self,
            .job_id = running_state.job_id,
            .attempt_id = running_state.attempt_id,
        };
        var result = (source.repairArtifactIssuesControlled(self.alloc, table_name, .{
            .target = target,
            .artifact_kind = running_state.kind,
            .index_name = running_state.index,
            .limit = running_state.limit,
            .cursor = running_state.cursor,
            .force = running_state.force,
            .repair_job_id = running_state.job_id,
            .repair_attempt_id = running_state.attempt_id,
            .repair_job_created_at_ms = running_state.created_at_millis,
        }, .{
            .cancel_check = .{
                .ptr = &cancel_probe,
                .is_requested = TableRepairCancelProbe.check,
            },
        }) catch |err| switch (err) {
            error.Canceled => {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .cancelled, "cancel_requested");
            },
            error.InvalidArgument => {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
            },
            error.NotFound => {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
            },
            else => {
                std.log.warn("public table repair job deferred table={s} job_id={d} err={}", .{ table_name, running_state.job_id, err });
                return try self.repair_job_store.recordRetryableFailure(self.alloc, running_state, @errorName(err));
            },
        }) orelse {
            return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
        };
        defer result.deinit(self.alloc);
        return try self.repair_job_store.recordPass(self.alloc, running_state, result);
    }

    pub fn handlePublicStartDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, body: []const u8) !public_table_http.OwnedResponse {
        if (self.table_writes == null) return try publicOperationTextResponse(self.alloc, 405, "method not allowed");
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.StartRequest, self.alloc, if (body.len > 0) body else "{}", .{}) catch {
            return try publicOperationTextResponse(self.alloc, 400, "invalid request");
        };
        defer parsed.deinit();

        const encoded = try self.artifact_reprocess_job_store.startJob(self.alloc, table_name, artifact_name, parsed.value);
        defer self.alloc.free(encoded);
        if (parsed.value.advance) {
            var parsed_state = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
                return try publicOperationTextResponse(self.alloc, 500, "artifact reprocess job failed");
            };
            defer parsed_state.deinit();
            return try self.advanceDocumentArtifactReprocessJobState(table_name, artifact_name, parsed_state.value);
        }
        return try publicOperationJsonResponse(self.alloc, 202, encoded);
    }

    pub fn handlePublicDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, encoded_job_id: []const u8) !public_table_http.OwnedResponse {
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try publicOperationTextResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.artifact_reprocess_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "artifact reprocess job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name) or !std.mem.eql(u8, parsed.value.artifact_name, artifact_name)) {
            return try publicOperationTextResponse(self.alloc, 404, "not found");
        }
        return try publicOperationJsonResponse(self.alloc, 200, encoded);
    }

    pub fn handlePublicAdvanceDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, encoded_job_id: []const u8) !public_table_http.OwnedResponse {
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try publicOperationTextResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.artifact_reprocess_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "artifact reprocess job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name) or !std.mem.eql(u8, parsed.value.artifact_name, artifact_name)) {
            return try publicOperationTextResponse(self.alloc, 404, "not found");
        }
        return try self.advanceDocumentArtifactReprocessJobState(table_name, artifact_name, parsed.value);
    }

    pub fn handlePublicCancelDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, encoded_job_id: []const u8) !public_table_http.OwnedResponse {
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try publicOperationTextResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.artifact_reprocess_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try publicOperationTextResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "artifact reprocess job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name) or !std.mem.eql(u8, parsed.value.artifact_name, artifact_name)) {
            return try publicOperationTextResponse(self.alloc, 404, "not found");
        }
        if (artifact_reprocess_jobs.isTerminalPhase(parsed.value.phase)) {
            return try publicOperationJsonResponse(self.alloc, 200, encoded);
        }
        const cancelled = try self.artifact_reprocess_job_store.requestCancel(self.alloc, parsed.value);
        defer self.alloc.free(cancelled);
        var parsed_cancelled = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, cancelled, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "invalid artifact reprocess job state");
        };
        defer parsed_cancelled.deinit();
        return try publicOperationJsonResponse(self.alloc, if (artifact_reprocess_jobs.isTerminalPhase(parsed_cancelled.value.phase)) 200 else 202, cancelled);
    }

    fn advanceDocumentArtifactReprocessJobState(self: *ApiHttpServer, table_name: []const u8, artifact_name: []const u8, state: artifact_reprocess_jobs.JobState) !public_table_http.OwnedResponse {
        if (artifact_reprocess_jobs.isTerminalPhase(state.phase)) {
            const encoded = try artifact_reprocess_jobs.encodeState(self.alloc, state);
            defer self.alloc.free(encoded);
            return try publicOperationJsonResponse(self.alloc, 200, encoded);
        }

        const begin = try self.artifact_reprocess_job_store.beginAdvance(self.alloc, state);
        defer self.alloc.free(begin.encoded);
        var parsed_running = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, begin.encoded, .{ .ignore_unknown_fields = true }) catch {
            return try publicOperationTextResponse(self.alloc, 500, "invalid job state");
        };
        defer parsed_running.deinit();
        const running_state = parsed_running.value;
        if (!begin.started) {
            return try publicOperationJsonResponse(self.alloc, if (artifact_reprocess_jobs.isTerminalPhase(running_state.phase)) 200 else 202, begin.encoded);
        }

        const source = self.table_writes orelse {
            const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
            defer self.alloc.free(failed);
            return try publicOperationTextResponse(self.alloc, 405, "method not allowed");
        };

        const shard_resumes = try self.alloc.alloc(db_mod.types.DocumentArtifactReprocessShardResume, running_state.shard_cursors.len);
        defer self.alloc.free(shard_resumes);
        for (running_state.shard_cursors, shard_resumes) |cursor, *out_resume| {
            out_resume.* = .{
                .group_id = cursor.group_id,
                .next_key = cursor.next_key,
                .limit = cursor.limit,
            };
        }
        const req = db_mod.types.DocumentArtifactTableReprocessRequest{
            .from_key = if (shard_resumes.len > 0) "" else (running_state.next_key orelse running_state.from_key),
            .to_key = running_state.to_key,
            .limit = running_state.limit,
            .shard_cursors = shard_resumes,
        };
        const result = source.reprocessDocumentArtifactRange(self.alloc, table_name, artifact_name, req) catch |err| switch (err) {
            error.DocIdentityNamespaceMismatch => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try publicOperationTextResponse(self.alloc, 503, "doc identity unavailable");
            },
            error.InvalidArgument => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try publicOperationTextResponse(self.alloc, 400, "invalid request");
            },
            error.NotFound => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try publicOperationTextResponse(self.alloc, 404, "not found");
            },
            else => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                std.log.err("public document artifact reprocess job failed table={s} artifact={s} job_id={d} err={}", .{ table_name, artifact_name, running_state.job_id, err });
                return try publicOperationTextResponse(self.alloc, 500, "artifact reprocess job failed");
            },
        };
        if (result == null) {
            const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
            defer self.alloc.free(failed);
            return try publicOperationTextResponse(self.alloc, 405, "method not allowed");
        }
        var pass = result.?;
        defer pass.deinit(self.alloc);
        const updated = try self.artifact_reprocess_job_store.recordPass(self.alloc, running_state, pass);
        defer self.alloc.free(updated);
        return try publicOperationJsonResponse(self.alloc, 202, updated);
    }

    pub fn handlePublicTableRestore(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        idempotency_key: ?[]const u8,
        principal: ?[]const u8,
    ) !contextual_operations.OwnedResponse {
        const parsed = backups_api.parseRestoreRequest(self.alloc, body) catch return try contextualJsonErrorResponse(self.alloc, 400, "invalid restore request");
        defer parsed.deinit();
        backups_api.validateBackupId(parsed.value.backup_id) catch return try contextualJsonErrorResponse(self.alloc, 400, "invalid backup id");
        const connection = parsed.value.connection;
        var location = backups_api.openBackupLocationWithOptions(self.alloc, parsed.value.location, .{
            .secret_store = self.cfg.secret_store,
            .node_config = self.cfg.node_config,
            .connection = connection,
            .required_capability = "restore.read",
            .io = self.sharedApiIo(),
        }) catch |err| return try contextualJsonErrorResponse(self.alloc, 400, backups_api.backupLocationErrorMessage(err) orelse "invalid restore location");
        location.deinit(self.alloc);
        self.ensureAsyncRestoreWorker() catch |err| return try restoreJobStartErrorResponse(self.alloc, err);
        const idempotency_namespace = try restoreIdempotencyNamespaceAlloc(self.alloc, principal, .table, table_name);
        defer self.alloc.free(idempotency_namespace);
        const encoded = self.restore_job_store.start(self.alloc, .{
            .scope = .table,
            .table_name = table_name,
            .backup_id = parsed.value.backup_id,
            .location = parsed.value.location,
            .connection = connection,
            .idempotency_namespace = idempotency_namespace,
            .idempotency_key = idempotency_key,
        }) catch |err| return try restoreJobStartErrorResponse(self.alloc, err);
        defer self.alloc.free(encoded);
        var state = try std.json.parseFromSlice(restore_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true });
        defer state.deinit();
        if (!restore_jobs.isTerminal(state.value.phase)) self.schedulePendingRestoreJobs() catch |err|
            std.log.err("accepted table restore job scheduling deferred job_id={d} err={s}", .{ state.value.job_id, @errorName(err) });
        return try self.restoreJobResponse(202, encoded);
    }

    pub fn handlePublicClusterRestore(
        self: *ApiHttpServer,
        body: []const u8,
        idempotency_key: ?[]const u8,
        principal: ?[]const u8,
    ) !contextual_operations.OwnedResponse {
        var req = backups_api.parseClusterRestoreRequest(self.alloc, body) catch return try contextualJsonErrorResponse(self.alloc, 400, "invalid restore request");
        defer backups_api.freeClusterRestoreRequest(self.alloc, &req);
        const connection = req.connection orelse return try contextualJsonErrorResponse(self.alloc, 400, "restore requires a named external_io connection");
        const restore_mode = backups_api.validateClusterRestoreMode(req.restore_mode) catch return try contextualJsonErrorResponse(self.alloc, 400, "invalid restore mode");
        var location = backups_api.openBackupLocationWithOptions(self.alloc, req.location, .{
            .secret_store = self.cfg.secret_store,
            .node_config = self.cfg.node_config,
            .connection = connection,
            .required_capability = "restore.read",
            .io = self.sharedApiIo(),
        }) catch |err| return try contextualJsonErrorResponse(self.alloc, 400, backups_api.backupLocationErrorMessage(err) orelse "invalid restore location");
        location.deinit(self.alloc);
        self.ensureAsyncRestoreWorker() catch |err| return try restoreJobStartErrorResponse(self.alloc, err);
        const idempotency_namespace = try restoreIdempotencyNamespaceAlloc(self.alloc, principal, .cluster, null);
        defer self.alloc.free(idempotency_namespace);
        const encoded = self.restore_job_store.start(self.alloc, .{
            .scope = .cluster,
            .backup_id = req.backup_id,
            .location = req.location,
            .connection = connection,
            .restore_mode = restore_mode,
            .table_names = req.table_names,
            .idempotency_namespace = idempotency_namespace,
            .idempotency_key = idempotency_key,
        }) catch |err| return try restoreJobStartErrorResponse(self.alloc, err);
        defer self.alloc.free(encoded);
        var state = try std.json.parseFromSlice(restore_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true });
        defer state.deinit();
        if (!restore_jobs.isTerminal(state.value.phase)) self.schedulePendingRestoreJobs() catch |err|
            std.log.err("accepted cluster restore job scheduling deferred job_id={d} err={s}", .{ state.value.job_id, @errorName(err) });
        return try self.restoreJobResponse(202, encoded);
    }

    pub fn resumeRestoreJobsOnce(self: *ApiHttpServer) !void {
        if (self.haMutationPolicy().failover_safe_mutations_only) return;
        if (self.restore_jobs_resumed.cmpxchgStrong(false, true, .acq_rel, .acquire) != null) return;
        self.schedulePendingRestoreJobs() catch |err| {
            self.restore_jobs_resumed.store(false, .release);
            return err;
        };
        try self.ensureRestoreRetryWakeup();
    }

    /// Cheap supervisor tick: the durable FIFO makes this O(available slots),
    /// not O(retained history). It retries transient dispatch failures without
    /// requiring another client request.
    pub fn pollRestoreJobsOnce(self: *ApiHttpServer) !void {
        try self.schedulePendingRestoreJobs();
        try self.ensureRestoreRetryWakeup();
    }

    fn ensureAsyncRestoreWorker(self: *ApiHttpServer) !void {
        if (self.restore_jobs_closing.load(.acquire)) return error.AsyncRestoreUnavailable;
        const runtime = self.cfg.backend_runtime orelse return error.AsyncRestoreUnavailable;
        if (runtime.threaded_jobs == null or
            self.restore_job_owner_id.load(.acquire) == 0)
            return error.AsyncRestoreUnavailable;
        if (!self.restore_job_store.hasPersistence()) return error.RestoreJobPersistenceUnavailable;
    }

    fn schedulePendingRestoreJobs(self: *ApiHttpServer) !void {
        self.restore_dispatch_requested.store(true, .release);
        while (true) {
            if (self.restore_jobs_closing.load(.acquire) or self.restore_dispatch_paused.load(.acquire)) return;
            if (!self.restore_dispatch_mutex.tryLock()) return;
            const dispatch_result = self.dispatchPendingRestoreJobsLocked();
            self.restore_dispatch_mutex.unlock();
            try dispatch_result;

            // A completion racing the final swap records another pass. If it
            // arrived after unlock it may already own the mutex; in either case
            // this loop is nonblocking and preserves one FIFO dispatcher.
            if (!self.restore_dispatch_requested.load(.acquire)) return;
        }
    }

    fn dispatchPendingRestoreJobsLocked(self: *ApiHttpServer) !void {
        while (self.restore_dispatch_requested.swap(false, .acq_rel)) {
            if (self.restore_jobs_closing.load(.acquire) or !self.restoreExecutionPermitted()) break;
            const runtime = self.cfg.backend_runtime orelse break;
            if (runtime.threaded_jobs == null or
                self.restore_job_owner_id.load(.acquire) == 0)
                break;
            platform_sync.lockYielding(&self.restore_schedule_mutex);
            const scheduled_count = self.scheduled_restore_jobs.count();
            self.restore_schedule_mutex.unlock();
            if (scheduled_count >= max_concurrent_restore_jobs) break;
            const ids = try self.restore_job_store.takePendingIds(self.alloc, max_concurrent_restore_jobs - scheduled_count);
            defer self.alloc.free(ids);
            for (ids) |job_id| {
                self.submitRestoreJob(job_id) catch |err| {
                    self.restore_job_store.requeuePending(job_id) catch |requeue_err| {
                        std.log.err("failed to requeue restore job job_id={d} err={s}", .{ job_id, @errorName(requeue_err) });
                    };
                    std.log.err("failed to schedule restore job job_id={d} err={s}", .{ job_id, @errorName(err) });
                };
            }
        }
    }

    fn submitRestoreJob(self: *ApiHttpServer, job_id: u64) !void {
        const runtime = self.cfg.backend_runtime orelse return error.AsyncRestoreUnavailable;
        const owner_id = self.restore_job_owner_id.load(.acquire);
        if (runtime.threaded_jobs == null or owner_id == 0)
            return error.AsyncRestoreUnavailable;
        platform_sync.lockYielding(&self.restore_schedule_mutex);
        if (self.scheduled_restore_jobs.contains(job_id)) {
            self.restore_schedule_mutex.unlock();
            return;
        }
        if (self.scheduled_restore_jobs.count() >= max_concurrent_restore_jobs) {
            self.restore_schedule_mutex.unlock();
            // Another concurrent scheduler filled the last slot after this
            // caller removed the job from the runnable queue. Surface that
            // race so the caller puts the job back instead of losing it until
            // the next process restart/leadership rebuild.
            return error.RestoreSchedulingCapacity;
        }
        self.scheduled_restore_jobs.put(self.alloc, job_id, {}) catch |err| {
            self.restore_schedule_mutex.unlock();
            return err;
        };
        self.restore_schedule_mutex.unlock();
        errdefer self.unmarkScheduledRestoreJob(job_id);
        const work = try self.alloc.create(RestoreJobWork);
        work.* = .{ .server = self, .job_id = job_id };
        runtime.durable_jobs.submit(.{
            .owner_id = owner_id,
            .class = .maintenance,
            .ptr = work,
            .run = RestoreJobWork.run,
            .deinit = RestoreJobWork.deinit,
        }) catch |err| {
            self.alloc.destroy(work);
            return err;
        };
    }

    fn restoreJobWorkCompleted(self: *ApiHttpServer, job_id: u64) void {
        self.unmarkScheduledRestoreJob(job_id);
        if (!self.restore_jobs_closing.load(.acquire)) self.schedulePendingRestoreJobs() catch |err| {
            std.log.err("failed to schedule pending restore jobs err={s}", .{@errorName(err)});
        };
        if (!self.restore_jobs_closing.load(.acquire)) self.ensureRestoreRetryWakeup() catch |err| {
            std.log.err("failed to schedule restore retry wakeup err={s}", .{@errorName(err)});
        };
    }

    /// Maintain one bounded shared timer for all delayed restores. Contended jobs
    /// leave the scarce execution slots immediately; the timer wakes the FIFO
    /// at the earliest durable eligibility deadline.
    fn ensureRestoreRetryWakeup(self: *ApiHttpServer) !void {
        if (self.restore_jobs_closing.load(.acquire)) return;
        const delay_ms = self.restore_job_store.nextPendingDelayMs() orelse return;
        if (delay_ms == 0) return;
        if (self.restore_retry_wakeup_in_flight.cmpxchgStrong(
            false,
            true,
            .acq_rel,
            .acquire,
        ) != null) return;
        errdefer self.restore_retry_wakeup_in_flight.store(false, .release);
        const runtime = self.cfg.backend_runtime orelse
            return error.AsyncRestoreUnavailable;
        const owner_id = self.restore_job_owner_id.load(.acquire);
        if (runtime.threaded_jobs == null or owner_id == 0)
            return error.AsyncRestoreUnavailable;
        const work = try self.alloc.create(RestoreRetryWakeWork);
        errdefer self.alloc.destroy(work);
        work.* = .{
            .server = self,
            .owner_id = owner_id,
        };
        try runtime.durable_jobs.submit(.{
            .owner_id = owner_id,
            .class = .maintenance,
            .ptr = work,
            .run = RestoreRetryWakeWork.run,
            .deinit = RestoreRetryWakeWork.deinit,
        });
    }

    fn signalRestoreRetryWakeup(self: *ApiHttpServer) void {
        _ = self.restore_retry_wakeup_generation.fetchAdd(1, .release);
        if (self.sharedApiIo()) |io| self.restore_retry_wakeup_event.set(io);
    }

    fn unmarkScheduledRestoreJob(self: *ApiHttpServer, job_id: u64) void {
        platform_sync.lockYielding(&self.restore_schedule_mutex);
        _ = self.scheduled_restore_jobs.remove(job_id);
        self.restore_schedule_mutex.unlock();
    }

    fn runRestoreJob(self: *ApiHttpServer, job_id: u64) !void {
        if (!self.restoreExecutionPermitted()) {
            try self.restore_job_store.requeuePending(job_id);
            return;
        }
        const running_encoded = (try self.restore_job_store.begin(self.alloc, job_id)) orelse return;
        defer self.alloc.free(running_encoded);
        var parsed = try std.json.parseFromSlice(restore_jobs.JobState, self.alloc, running_encoded, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        const state = parsed.value;
        if (state.phase != .running) return;
        var location = backups_api.openBackupLocationWithOptions(self.alloc, state.location, .{
            .secret_store = self.cfg.secret_store,
            .node_config = self.cfg.node_config,
            .connection = state.connection,
            .required_capability = "restore.read",
            .io = self.sharedApiIo(),
        }) catch |err| {
            const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(err));
            self.alloc.free(failed);
            return;
        };
        defer location.deinit(self.alloc);
        const result = switch (state.scope) {
            .table => blk: {
                if (!self.restoreExecutionPermitted()) return error.RestoreJobFenced;
                const table_name = state.table_name orelse return error.CorruptRestoreJobStore;
                var restored_via_metadata = false;
                if (!restore_jobs.containsTableIndex(state.published_table_ranges orelse &.{}, 0)) {
                    if (!restore_jobs.tableAttempted(state, 0)) {
                        self.checkpointRestoreTableStarted(.{ .job_id = state.job_id, .attempt_id = state.attempt_id }, 0) catch |err| {
                            if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.RestoreJobFenced;
                            const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(err));
                            self.alloc.free(failed);
                            return;
                        };
                    }
                    restored_via_metadata = true;
                    executePublicTableRestore(
                        self,
                        self.alloc,
                        table_name,
                        state.backup_id,
                        state.location,
                        state.connection,
                        &location,
                        .{},
                    ) catch |err| switch (err) {
                        // The local owned-table path reports durable completion as
                        // a sentinel because the public callback otherwise has no
                        // result channel. Preserve that distinction: only a normal
                        // return came through metadata reconciliation and owns a
                        // distributed restore intent to wait on below.
                        error.RestoreDurabilityConfirmed => restored_via_metadata = false,
                        error.RestoreDurabilityPending => {
                            self.checkpointRestoreTableDurabilityPending(.{ .job_id = state.job_id, .attempt_id = state.attempt_id }, 0) catch |checkpoint_err| {
                                if (checkpoint_err == error.RestoreJobFenced or metadata_authority.isRetryableError(checkpoint_err)) return error.RestoreJobFenced;
                                const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(checkpoint_err));
                                self.alloc.free(failed);
                                return;
                            };
                            const pending_result = try backups_api.encodeRestoreDurabilityPending(self.alloc);
                            defer self.alloc.free(pending_result);
                            const failed = try self.restore_job_store.failWithResult(self.alloc, state, pending_result, "RestoreDurabilityPending");
                            self.alloc.free(failed);
                            return;
                        },
                        else => {
                            const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(err));
                            self.alloc.free(failed);
                            return;
                        },
                    };
                    self.checkpointRestoreTablePublished(.{ .job_id = state.job_id, .attempt_id = state.attempt_id }, 0) catch |err| {
                        if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.RestoreJobFenced;
                        const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(err));
                        self.alloc.free(failed);
                        return;
                    };
                } else if (!self.cfg.deployment_mode.isStandalone()) {
                    // A resumed job may already have crossed publication. Infer
                    // which completion protocol owns it from durable metadata;
                    // local fallback restores intentionally have no such intent.
                    restored_via_metadata = switch (try self.distributedRestoreIntentState(table_name, state.location, state.backup_id, state.backup_id)) {
                        .pending, .completed => true,
                        .missing => false,
                        .conflicting => {
                            const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(error.RestoreIntentConflict));
                            self.alloc.free(failed);
                            return;
                        },
                    };
                }
                if (restored_via_metadata and !self.cfg.deployment_mode.isStandalone()) {
                    self.waitForDistributedRestoreCompletion(table_name, state.location, state.backup_id, state.backup_id, .{ .job_id = state.job_id, .attempt_id = state.attempt_id }) catch |err| {
                        if (metadata_authority.isRetryableError(err)) return error.RestoreJobFenced;
                        const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(err));
                        self.alloc.free(failed);
                        return;
                    };
                }
                self.checkpointRestoreTableCompleted(.{ .job_id = state.job_id, .attempt_id = state.attempt_id }, 0) catch |err| {
                    if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.RestoreJobFenced;
                    const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(err));
                    self.alloc.free(failed);
                    return;
                };
                if (!self.restoreExecutionPermitted()) return error.RestoreJobFenced;
                break :blk try backups_api.encodeRestoreTriggered(self.alloc);
            },
            .cluster => executePublicClusterRestoreWithCancellation(self, self.alloc, .{
                .backup_id = state.backup_id,
                .location = state.location,
                .connection = state.connection,
                .table_names = state.table_names,
                .restore_mode = state.restore_mode,
            }, &location, state.restore_mode, .{ .job_id = state.job_id, .attempt_id = state.attempt_id }, state.active_table_index, state.durability_pending_table_ranges orelse &.{}, state.published_table_ranges orelse &.{}) catch |err| {
                if (err == error.BackupRepositoryBusy) {
                    const retry_delay_ns = restoreRepositoryRetryDelayNs(
                        state.job_id,
                        state.attempt_id,
                    );
                    const retried = try self.restore_job_store.retryRunning(
                        self.alloc,
                        state,
                        @errorName(err),
                        retry_delay_ns,
                    );
                    self.alloc.free(retried);
                    self.signalRestoreRetryWakeup();
                    try self.ensureRestoreRetryWakeup();
                    return;
                }
                if (err == error.NotLeader or err == error.RestoreJobFenced) {
                    return error.RestoreJobFenced;
                }
                const failed = try self.restore_job_store.fail(self.alloc, state, @errorName(err));
                self.alloc.free(failed);
                return;
            },
        };
        defer self.alloc.free(result);
        var cluster_summary: ?restore_jobs.ClusterResultSummary = null;
        if (state.scope == .cluster) cluster_summary = try restore_jobs.summarizeClusterResultAlloc(self.alloc, result);
        defer if (cluster_summary) |*summary| summary.deinit(self.alloc);
        const terminal_result = if (cluster_summary) |summary| summary.encoded else result;
        const finished = if (cluster_summary) |summary|
            if (summary.succeeded)
                try self.restore_job_store.finish(self.alloc, state, terminal_result)
            else
                try self.restore_job_store.failWithResult(
                    self.alloc,
                    state,
                    terminal_result,
                    if (summary.durability_pending) "RestoreDurabilityPending" else "ClusterRestorePartialFailure",
                )
        else
            try self.restore_job_store.finish(self.alloc, state, terminal_result);
        self.alloc.free(finished);
    }

    pub fn handlePublicRestoreJob(self: *ApiHttpServer, job_id: u64, cancel: bool) !contextual_operations.OwnedResponse {
        const encoded = if (cancel) blk: {
            const cancelled = (try self.restore_job_store.cancel(self.alloc, job_id)) orelse
                return try contextualJsonErrorResponse(self.alloc, 404, "not found");
            self.signalRestoreRetryWakeup();
            break :blk cancelled;
        } else (try self.restore_job_store.load(self.alloc, job_id)) orelse return try contextualJsonErrorResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        return try self.restoreJobResponse(200, encoded);
    }

    pub const RestoreJobListOptions = struct {
        limit: usize = 50,
        cursor: ?u64 = null,
        phase: ?restore_jobs.Phase = null,
        scope: ?restore_jobs.Scope = null,
    };

    const restore_job_public_scan_batch_size: usize = 64;
    const restore_job_public_scan_budget: usize = 128;

    pub fn handlePublicListRestoreJobs(
        self: *ApiHttpServer,
        identity: ?AuthenticatedIdentity,
        options: RestoreJobListOptions,
    ) !contextual_operations.OwnedResponse {
        if (options.limit == 0 or options.limit > 100) return try contextualJsonErrorResponse(self.alloc, 400, "invalid restore job list limit");

        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const arena = arena_impl.allocator();
        var jobs = std.ArrayListUnmanaged(RestoreJobView).empty;
        defer jobs.deinit(arena);
        try jobs.ensureTotalCapacity(arena, options.limit);

        var scan_cursor = options.cursor;
        var last_returned_sequence: ?u64 = null;
        var continuation_cursor: ?u64 = null;
        var scanned: usize = 0;
        scan: while (true) {
            const remaining_budget = restore_job_public_scan_budget - scanned;
            if (remaining_budget == 0) {
                continuation_cursor = scan_cursor;
                break;
            }
            var batch = try self.restore_job_store.listBatch(
                self.alloc,
                scan_cursor,
                @min(restore_job_public_scan_batch_size, remaining_budget),
            );
            defer batch.deinit(self.alloc);
            if (batch.records.len == 0) break;
            scanned += batch.records.len;
            for (batch.records) |encoded| {
                var parsed = try std.json.parseFromSlice(restore_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true });
                defer parsed.deinit();
                const state = parsed.value;
                if (options.phase) |phase| if (state.phase != phase) continue;
                if (options.scope) |scope| if (state.scope != scope) continue;
                if (identity) |authenticated| {
                    if (!restoreJobStateAllowed(authenticated, state)) continue;
                }
                if (jobs.items.len == options.limit) {
                    continuation_cursor = last_returned_sequence;
                    break :scan;
                }
                jobs.appendAssumeCapacity(try restoreJobViewFromStateAlloc(arena, state));
                last_returned_sequence = state.enqueue_sequence;
            }
            scan_cursor = batch.next_scan_cursor orelse break;
            if (scanned == restore_job_public_scan_budget) {
                continuation_cursor = scan_cursor;
                break;
            }
        }

        const next_cursor = if (continuation_cursor) |value| try std.fmt.allocPrint(arena, "{d}", .{value}) else null;
        return try contextualJsonResponseOmitNullOptionals(self.alloc, 200, .{
            .jobs = jobs.items,
            .next_cursor = next_cursor,
        });
    }

    pub fn restoreJobAllowed(self: *ApiHttpServer, alloc: std.mem.Allocator, identity: AuthenticatedIdentity, job_id: u64) !bool {
        const encoded = (try self.restore_job_store.load(alloc, job_id)) orelse return false;
        defer alloc.free(encoded);
        var parsed = try std.json.parseFromSlice(restore_jobs.JobState, alloc, encoded, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        return restoreJobStateAllowed(identity, parsed.value);
    }

    fn restoreJobStateAllowed(identity: AuthenticatedIdentity, state: restore_jobs.JobState) bool {
        return switch (state.scope) {
            .cluster => permissionsAllow(identity.permissions, .@"*", "*", .admin),
            .table => permissionsAllow(identity.permissions, .table, state.table_name orelse return false, .admin),
        };
    }

    const RestoreJobView = struct {
        job_id: []const u8,
        attempt_id: u64,
        scope: restore_jobs.Scope,
        table_name: ?[]const u8,
        backup_id: []const u8,
        phase: restore_jobs.Phase,
        cancel_requested: bool,
        durability_pending_table_count: usize,
        published_table_count: usize,
        completed_table_count: usize,
        total_table_count: ?usize,
        result: ?std.json.Value,
        @"error": ?[]const u8,
        created_at_ms: u64,
        updated_at_ms: u64,
        expires_at_ms: ?u64,
    };

    fn restoreJobViewAlloc(arena: std.mem.Allocator, encoded: []const u8) !RestoreJobView {
        var parsed = try std.json.parseFromSlice(restore_jobs.JobState, arena, encoded, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        return try restoreJobViewFromStateAlloc(arena, parsed.value);
    }

    fn restoreJobViewFromStateAlloc(arena: std.mem.Allocator, state: restore_jobs.JobState) !RestoreJobView {
        const result: ?std.json.Value = if (state.result_json) |raw| blk: {
            const value = try std.json.parseFromSlice(std.json.Value, arena, raw, .{});
            break :blk value.value;
        } else null;
        return .{
            .job_id = try std.fmt.allocPrint(arena, "{d}", .{state.job_id}),
            .attempt_id = state.attempt_id,
            .scope = state.scope,
            .table_name = if (state.table_name) |table_name| try arena.dupe(u8, table_name) else null,
            .backup_id = try arena.dupe(u8, state.backup_id),
            .phase = state.phase,
            .cancel_requested = state.cancel_requested,
            .durability_pending_table_count = restore_jobs.tableIndexRangeCount(state.durability_pending_table_ranges orelse &.{}),
            .published_table_count = restore_jobs.tableIndexRangeCount(state.published_table_ranges orelse &.{}),
            .completed_table_count = restore_jobs.tableIndexRangeCount(state.completed_table_ranges orelse &.{}),
            .total_table_count = if (state.scope == .table) @as(usize, 1) else if (state.table_names) |names| names.len else null,
            .result = result,
            .@"error" = if (state.last_error) |last_error| try arena.dupe(u8, last_error) else null,
            .created_at_ms = state.created_at_ms,
            .updated_at_ms = state.updated_at_ms,
            .expires_at_ms = if (restore_jobs.isTerminal(state.phase)) state.expires_at_ms else null,
        };
    }

    fn restoreJobResponse(self: *ApiHttpServer, status: u16, encoded: []const u8) !contextual_operations.OwnedResponse {
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const arena = arena_impl.allocator();
        const view = try restoreJobViewAlloc(arena, encoded);
        var response = try contextualJsonResponseOmitNullOptionals(self.alloc, status, view);
        if (status == 202) {
            response.headers = try self.alloc.alloc(contextual_operations.Header, 2);
            var initialized: usize = 0;
            errdefer {
                for (response.headers[0..initialized]) |*header| header.deinit(self.alloc);
                self.alloc.free(response.headers);
                response.headers = &.{};
                response.deinit(self.alloc);
            }
            const location_value = try std.fmt.allocPrint(self.alloc, "/db/v1/restore/jobs/{s}", .{view.job_id});
            defer self.alloc.free(location_value);
            response.headers[0] = try ownedContextualHeader(self.alloc, "Location", location_value);
            initialized += 1;
            response.headers[1] = try ownedContextualHeader(self.alloc, "Retry-After", "1");
        }
        return response;
    }
};

const RestoreRetryWakeWork = struct {
    server: *ApiHttpServer,
    owner_id: u64,

    fn run(ptr: *anyopaque) !void {
        const self: *RestoreRetryWakeWork = @ptrCast(@alignCast(ptr));
        const io = self.server.sharedApiIo() orelse
            return error.AsyncRestoreUnavailable;
        while (!self.server.restore_jobs_closing.load(.acquire) and
            self.server.restore_job_owner_id.load(.acquire) == self.owner_id)
        {
            const observed_generation =
                self.server.restore_retry_wakeup_generation.load(.acquire);
            const delay_ms = self.server.restore_job_store.nextPendingDelayMs() orelse
                return;
            if (delay_ms == 0) {
                try self.server.schedulePendingRestoreJobs();
                return;
            }
            _ = waitForRestoreRetryDeadline(
                io,
                &self.server.restore_retry_wakeup_event,
                &self.server.restore_retry_wakeup_generation,
                observed_generation,
                delay_ms,
            ) catch |err| switch (err) {
                error.Canceled => return,
            };
        }
    }

    fn deinit(ptr: *anyopaque) void {
        const self: *RestoreRetryWakeWork = @ptrCast(@alignCast(ptr));
        const server = self.server;
        server.alloc.destroy(self);
        server.restore_retry_wakeup_in_flight.store(false, .release);
        if (server.restore_jobs_closing.load(.acquire)) return;
        if (server.restore_job_owner_id.load(.acquire) == 0) return;
        if ((server.restore_job_store.nextPendingDelayMs() orelse 0) == 0) return;
        // A leadership handoff closes the old owner while this bounded sleeper
        // is still in flight. Once its shared slot is released, transfer the
        // wakeup responsibility to the current owner instead of waiting for an
        // unrelated request or supervisor tick.
        server.ensureRestoreRetryWakeup() catch |err| {
            std.log.err("failed to reschedule restore retry wakeup err={s}", .{@errorName(err)});
        };
    }
};

/// Wait once until the durable eligibility deadline or a queue/ownership
/// change. The generation check closes the set-before-reset race: a signal
/// that arrives between the caller's snapshot and `reset` cannot be lost.
fn waitForRestoreRetryDeadline(
    io: std.Io,
    event: *std.Io.Event,
    generation: *std.atomic.Value(u64),
    observed_generation: u64,
    delay_ms: u64,
) error{Canceled}!bool {
    event.reset();
    if (generation.load(.acquire) != observed_generation) return false;
    const bounded_delay_ms: i64 = @intCast(@min(
        delay_ms,
        @as(u64, @intCast(std.math.maxInt(i64))),
    ));
    event.waitTimeout(io, .{
        .duration = .{
            .raw = std.Io.Duration.fromMilliseconds(bounded_delay_ms),
            .clock = .awake,
        },
    }) catch |err| switch (err) {
        error.Timeout => return true,
        error.Canceled => return error.Canceled,
    };
    return false;
}

test "restore retry deadline wakeup is interruptible without polling" {
    var io_impl = std.Io.Threaded.init(std.testing.allocator, .{});
    defer io_impl.deinit();
    const io = io_impl.io();
    var event: std.Io.Event = .unset;
    var generation: std.atomic.Value(u64) = .init(0);
    const observed_generation = generation.load(.acquire);
    const Wake = struct {
        fn run(
            wake_io: std.Io,
            wake_event: *std.Io.Event,
            wake_generation: *std.atomic.Value(u64),
        ) void {
            wake_io.sleep(std.Io.Duration.fromMilliseconds(1), .awake) catch {};
            _ = wake_generation.fetchAdd(1, .release);
            wake_event.set(wake_io);
        }
    };
    var wake = try io.concurrent(Wake.run, .{ io, &event, &generation });
    defer _ = wake.await(io);
    try std.testing.expect(!try waitForRestoreRetryDeadline(
        io,
        &event,
        &generation,
        observed_generation,
        60 * 1000,
    ));
}

const RestoreJobWork = struct {
    server: *ApiHttpServer,
    job_id: u64,

    fn run(ptr: *anyopaque) !void {
        const self: *RestoreJobWork = @ptrCast(@alignCast(ptr));
        self.server.runRestoreJob(self.job_id) catch |err| {
            // Leadership rebuilds recover running attempts into the durable
            // FIFO. The old owner must never turn a correctly fenced attempt
            // into a terminal failure while leadership is moving.
            if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return;
            std.log.err("restore job execution failed job_id={d} err={s}", .{ self.job_id, @errorName(err) });
            self.server.restore_job_store.failRunningById(self.server.alloc, self.job_id, @errorName(err)) catch |persist_err| {
                std.log.err("failed to persist restore job failure job_id={d} err={s}", .{ self.job_id, @errorName(persist_err) });
            };
        };
    }

    fn deinit(ptr: *anyopaque) void {
        const self: *RestoreJobWork = @ptrCast(@alignCast(ptr));
        self.server.restoreJobWorkCompleted(self.job_id);
        self.server.alloc.destroy(self);
    }
};

fn restoreJobIdFromPath(path: []const u8) ?u64 {
    const prefix = routes.Routes.restore ++ "/jobs/";
    if (!std.mem.startsWith(u8, path, prefix)) return null;
    const raw = path[prefix.len..];
    if (raw.len == 0 or std.mem.indexOfScalar(u8, raw, '/') != null) return null;
    return std.fmt.parseUnsigned(u64, raw, 10) catch null;
}

fn restoreJobStartErrorResponse(alloc: std.mem.Allocator, err: anyerror) !contextual_operations.OwnedResponse {
    if (metadata_authority.isRetryableError(err)) return try contextualRetryableJsonErrorResponse(alloc, 503, "metadata leader unavailable");
    return switch (err) {
        error.InvalidIdempotencyKey => try contextualJsonErrorResponse(alloc, 400, "invalid idempotency key"),
        error.IdempotencyConflict => try contextualJsonErrorResponse(alloc, 409, "idempotency key reused for a different restore"),
        error.AsyncRestoreUnavailable => try contextualJsonErrorResponse(alloc, 503, "asynchronous restore worker unavailable"),
        error.RestoreJobPersistenceUnavailable => try contextualJsonErrorResponse(alloc, 503, "durable restore store unavailable"),
        error.RestoreJobCapacityExceeded => try contextualJsonErrorResponse(alloc, 503, "restore job history is at capacity"),
        error.RestoreJobRecordTooLarge, error.TooManyRestoreTables => try contextualJsonErrorResponse(alloc, 400, "restore request is too large"),
        error.DuplicateRestoreTableName => try contextualJsonErrorResponse(alloc, 400, "restore request contains duplicate table names"),
        else => try contextualJsonErrorResponse(alloc, 500, "failed to create restore job"),
    };
}

