fn waitForTerminalRestoreJobAlloc(alloc: std.mem.Allocator, server: *ApiHttpServer, response_body: []const u8) ![]u8 {
    var response = try std.json.parseFromSlice(struct { job_id: []const u8 }, alloc, response_body, .{ .ignore_unknown_fields = true });
    defer response.deinit();
    const job_id = try std.fmt.parseUnsigned(u64, response.value.job_id, 10);

    var attempts: usize = 0;
    while (attempts < 5000) : (attempts += 1) {
        const encoded = (try server.restore_job_store.load(alloc, job_id)) orelse return error.TestUnexpectedResult;
        var state = std.json.parseFromSlice(restore_jobs.JobState, alloc, encoded, .{ .ignore_unknown_fields = true }) catch |err| {
            alloc.free(encoded);
            return err;
        };
        const terminal = restore_jobs.isTerminal(state.value.phase);
        state.deinit();
        if (terminal) return encoded;
        alloc.free(encoded);
        sleepNs(std.time.ns_per_ms);
    }
    return error.TestUnexpectedResult;
}

fn sleepNs(duration_ns: u64) void {
    var req = std.posix.timespec{
        .sec = @intCast(duration_ns / std.time.ns_per_s),
        .nsec = @intCast(duration_ns % std.time.ns_per_s),
    };
    while (true) switch (std.posix.errno(std.posix.system.nanosleep(&req, &req))) {
        .SUCCESS => return,
        .INTR => continue,
        else => return,
    };
}

fn retryDeadlineExpired(deadline_ns: ?u64, now_ns: u64) bool {
    const deadline = deadline_ns orelse return false;
    return now_ns >= deadline;
}

fn ensureRequestDeadline(deadline_ns: ?u64) !void {
    if (retryDeadlineExpired(deadline_ns, platform_time.monotonicNs())) return error.Timeout;
}

fn ensureRequestActive(cancellation: ?CancellationToken) !void {
    if (cancellation) |value| {
        if (value.isCancelled()) return error.Cancelled;
    }
}

fn ensureTableOperationActive(request: api_operation.RequestContext) error{ Canceled, DeadlineExceeded }!void {
    request.ensureActive() catch |err| switch (err) {
        error.Canceled => return error.Canceled,
        error.DeadlineExceeded => return error.DeadlineExceeded,
        else => unreachable,
    };
}

fn sleepNsCancellable(duration_ns: u64, cancellation: ?CancellationToken) !void {
    // Retry sleeps are deliberately broken into short slices so a vanished
    // peer does not occupy an expensive query slot for the full backoff.
    var remaining = duration_ns;
    while (remaining > 0) {
        try ensureRequestActive(cancellation);
        const slice = @min(remaining, 5 * std.time.ns_per_ms);
        sleepNs(slice);
        remaining -= slice;
    }
    try ensureRequestActive(cancellation);
}

fn boundedRetrySleepNs(
    deadline_ns: ?u64,
    now_ns: u64,
    retry_start_ns: u64,
    retry_timeout_ns: u64,
    retry_poll_ns: u64,
) ?u64 {
    if (retry_timeout_ns == 0) return null;
    const retry_elapsed_ns = now_ns -| retry_start_ns;
    if (retry_elapsed_ns >= retry_timeout_ns) return null;

    var sleep_ns = @min(retry_poll_ns, retry_timeout_ns - retry_elapsed_ns);
    if (deadline_ns) |deadline| {
        if (now_ns >= deadline) return 0;
        sleep_ns = @min(sleep_ns, deadline - now_ns);
    }
    return sleep_ns;
}

fn testMetadataServiceSourceWithoutLifecycle(svc: *metadata_service.MetadataService) StatusSource {
    const V = struct {
        fn status(ptr: *anyopaque) anyerror!metadata_api.MetadataStatus {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            return try service.status();
        }

        fn adminSnapshot(ptr: *anyopaque) anyerror!metadata_api.AdminSnapshot {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            return try service.adminSnapshot();
        }

        fn cachedAdminSnapshot(ptr: *anyopaque) anyerror!?metadata_api.AdminSnapshot {
            return try adminSnapshot(ptr);
        }

        fn freeAdminSnapshot(ptr: *anyopaque, snapshot: *metadata_api.AdminSnapshot) void {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            service.freeAdminSnapshot(snapshot);
        }

        fn createTable(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, req: tables_api.CreateTableRequest) anyerror!void {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            return try createTableOnService(service, alloc, table_name, req);
        }

        fn dropTable(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8) anyerror!void {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            return try dropTableOnService(service, alloc, table_name);
        }

        fn updateSchema(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) anyerror!void {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            _ = try updateSchemaOnService(service, alloc, table_name, schema_json);
        }

        fn updateSchemaVersioned(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) anyerror!u32 {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            return try updateSchemaOnService(service, alloc, table_name, schema_json);
        }

        fn createIndex(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8, index_json: []const u8) anyerror!void {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            return try createIndexOnService(service, alloc, table_name, index_name, index_json);
        }

        fn dropIndex(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8) anyerror!void {
            const service: *metadata_service.MetadataService = @ptrCast(@alignCast(ptr));
            return try dropIndexOnService(service, alloc, table_name, index_name);
        }
    };

    return .{
        .ptr = svc,
        .vtable = &.{
            .status = V.status,
            .admin_snapshot = V.adminSnapshot,
            .cached_admin_snapshot = V.cachedAdminSnapshot,
            .free_admin_snapshot = V.freeAdminSnapshot,
            .create_table = V.createTable,
            .drop_table = V.dropTable,
            .update_schema = V.updateSchema,
            .update_schema_versioned = V.updateSchemaVersioned,
            .create_index = V.createIndex,
            .drop_index = V.dropIndex,
        },
    };
}

pub fn freeOwnedStrings(alloc: std.mem.Allocator, values: []const []const u8) void {
    for (values) |value| alloc.free(@constCast(value));
    if (values.len > 0) alloc.free(@constCast(values));
}

fn cloneOwnedStrings(alloc: std.mem.Allocator, values: []const []const u8) ![][]u8 {
    const out = try alloc.alloc([]u8, values.len);
    var initialized: usize = 0;
    errdefer {
        for (out[0..initialized]) |value| alloc.free(value);
        if (out.len > 0) alloc.free(out);
    }
    for (values, 0..) |value, i| {
        out[i] = try alloc.dupe(u8, value);
        initialized += 1;
    }
    return out;
}

fn freeOwnedStringItems(alloc: std.mem.Allocator, values: []const []const u8) void {
    for (values) |value| alloc.free(@constCast(value));
}

