    errdefer {
        for (owned[0..initialized]) |name| alloc.free(name);
        alloc.free(owned);
    }
    for (names, 0..) |name, i| {
        owned[i] = try alloc.dupe(u8, name);
        initialized += 1;
    }
    return owned;
}

