test "api http server durably retries table repair job when background submit is closing" {
    if (@import("builtin").os.tag == .freestanding) return error.SkipZigTest;

    const alloc = std.testing.allocator;
    var runtime = try db_mod.background_runtime.BackendRuntimeHandle.init(alloc, .{});
    defer runtime.deinit();

    const DummyStatus = struct {
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };

    var server = ApiHttpServer.init(alloc, .{
        .backend_runtime = runtime.ptr(),
    }, .{
        .ptr = undefined,
        .vtable = &.{ .status = DummyStatus.status },
    }, null, null);
    defer server.deinit();

    const started = try server.repair_job_store.startJob(alloc, "docs", .{
        .target = "artifact",
        .limit = 1,
    });
    defer alloc.free(started);
    var parsed_started = try std.json.parseFromSlice(repair_jobs.JobState, alloc, started, .{ .ignore_unknown_fields = true });
    defer parsed_started.deinit();

    const begin = try server.repair_job_store.beginAdvance(alloc, parsed_started.value);
    defer alloc.free(begin.encoded);
    try std.testing.expect(begin.started);
    var parsed_running = try std.json.parseFromSlice(repair_jobs.JobState, alloc, begin.encoded, .{ .ignore_unknown_fields = true });
    defer parsed_running.deinit();

    runtime.ptr().durable_jobs.closeOwner(server.repair_job_owner_id);
    const updated = (try server.submitTableRepairJobPass("docs", begin.encoded, parsed_running.value.job_id)).?;
    defer alloc.free(updated);

    var parsed_updated = try std.json.parseFromSlice(repair_jobs.JobState, alloc, updated, .{ .ignore_unknown_fields = true });
    defer parsed_updated.deinit();
    try std.testing.expectEqualStrings("queued", parsed_updated.value.phase);
    try std.testing.expectEqualStrings("BackgroundOwnerClosed", parsed_updated.value.last_error.?);
    try std.testing.expect(parsed_updated.value.next_retry_at_millis > parsed_updated.value.last_updated_at_millis);
}

test "api maintenance resumes recovered durable named index cancellation without client advance" {
    const alloc = std.testing.allocator;
    const DummyStatus = struct {
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };
    const FakeWrites = struct {
        calls: usize = 0,

        fn batch(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) anyerror!?void {
            return null;
        }

        fn repair(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            table_name: []const u8,
            req: db_mod.types.ArtifactRepairRunRequest,
            _: db_mod.types.ArtifactRepairRunOptions,
        ) anyerror!?db_mod.types.ArtifactRepairResult {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expectEqual(db_mod.types.RepairTarget.index, req.target);
            try std.testing.expectEqual(db_mod.types.IndexRepairControl.pause_automatic, req.control.?);
            self.calls += 1;
            return .{
                .scanned = 1,
                .groups_scanned = 1,
                .controls_applied = 1,
            };
        }

        fn source(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .repair_artifact_issues_controlled = repair,
                },
            };
        }
    };

    var writes = FakeWrites{};
    var server = ApiHttpServer.init(alloc, .{}, .{
        .ptr = undefined,
        .vtable = &.{ .status = DummyStatus.status },
    }, null, writes.source());
    defer server.deinit();

    const started = try server.repair_job_store.startJob(alloc, "docs", .{
        .target = "index",
        .index = "semantic",
    });
    defer alloc.free(started);
    var parsed_started = try std.json.parseFromSlice(repair_jobs.JobState, alloc, started, .{ .ignore_unknown_fields = true });
    defer parsed_started.deinit();
    const cancelling = try server.repair_job_store.requestCancel(alloc, parsed_started.value);
    defer alloc.free(cancelling);

    try server.runSessionMaintenanceOnce();
    try std.testing.expectEqual(@as(usize, 1), writes.calls);
    const finished = (try server.repair_job_store.loadJobAlloc(alloc, parsed_started.value.job_id)).?;
    defer alloc.free(finished);
    var parsed_finished = try std.json.parseFromSlice(repair_jobs.JobState, alloc, finished, .{ .ignore_unknown_fields = true });
    defer parsed_finished.deinit();
    try std.testing.expectEqualStrings("cancelled", parsed_finished.value.phase);
}

fn base64UrlDecodeAlloc(alloc: std.mem.Allocator, value: []const u8) ![]u8 {
    const size = std.base64.url_safe_no_pad.Decoder.calcSizeForSlice(value) catch return error.Unauthorized;
    const out = try alloc.alloc(u8, size);
    errdefer alloc.free(out);
    std.base64.url_safe_no_pad.Decoder.decode(out, value) catch return error.Unauthorized;
    return out;
}

pub fn constantTimeEql(lhs: []const u8, rhs: []const u8) bool {
    if (lhs.len != rhs.len) return false;
    var diff: u8 = 0;
    for (lhs, rhs) |left, right| diff |= left ^ right;
    return diff == 0;
}

fn jsonStringField(value: ?std.json.Value) ?[]const u8 {
    const present = value orelse return null;
    return jsonStringValue(present);
}

fn jsonStringValue(value: std.json.Value) ?[]const u8 {
    return switch (value) {
        .string => |string| string,
        else => null,
    };
}

fn jsonIntegerField(value: ?std.json.Value) ?i64 {
    const present = value orelse return null;
    return jsonIntegerValue(present);
}

fn jsonIntegerValue(value: std.json.Value) ?i64 {
    return switch (value) {
        .integer => |integer| integer,
        else => null,
    };
}

fn jsonBoolField(value: ?std.json.Value) bool {
    const present = value orelse return false;
    return jsonBoolValue(present);
}

fn jsonBoolValue(value: std.json.Value) bool {
    return switch (value) {
        .bool => |boolean| boolean,
        else => false,
    };
}

fn trustedPrincipalPermissionsFromPayload(alloc: std.mem.Allocator, payload: std.json.ObjectMap) ![]usermgr.Permission {
    var out = std.ArrayList(usermgr.Permission).empty;
    errdefer {
        for (out.items) |*permission| permission.deinit(alloc);
        out.deinit(alloc);
    }

    if (jsonBoolField(payload.get("admin"))) {
        try out.append(alloc, try usermgr.Permission.initOwned(alloc, .@"*", "*", .admin));
        return try out.toOwnedSlice(alloc);
    }

    const tables_value = payload.get("tables");
    const operations_value = payload.get("operations");
    if (operations_value == null or operations_value.? != .array or operations_value.?.array.items.len == 0) {
        return try out.toOwnedSlice(alloc);
    }

    if (tables_value == null or tables_value.? != .array or tables_value.?.array.items.len == 0) {
        try appendTrustedPrincipalPermissionsForTable(alloc, &out, "*", operations_value.?.array.items);
    } else {
        for (tables_value.?.array.items) |table_value| {
            const table = jsonStringValue(table_value) orelse continue;
            if (table.len == 0) continue;
            try appendTrustedPrincipalPermissionsForTable(alloc, &out, table, operations_value.?.array.items);
        }
    }
    return try out.toOwnedSlice(alloc);
}

fn appendTrustedPrincipalPermissionsForTable(
    alloc: std.mem.Allocator,
    out: *std.ArrayList(usermgr.Permission),
    table: []const u8,
    operation_values: []const std.json.Value,
) !void {
    for (operation_values) |operation_value| {
        const operation = jsonStringValue(operation_value) orelse continue;
        if (std.mem.eql(u8, operation, "read")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .read));
        } else if (std.mem.eql(u8, operation, "write")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .write));
        } else if (std.mem.eql(u8, operation, "admin")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .admin));
        } else if (std.mem.eql(u8, operation, "*")) {
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .read));
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .write));
            try out.append(alloc, try usermgr.Permission.initOwned(alloc, .table, table, .admin));
        }
    }
}

fn trustedPrincipalRowFiltersFromPayload(alloc: std.mem.Allocator, payload: std.json.ObjectMap) ![]usermgr.RowFilterEntry {
    const row_filter_value = payload.get("row_filter") orelse return try alloc.alloc(usermgr.RowFilterEntry, 0);
    if (row_filter_value != .object) return error.Unauthorized;
    var out = std.ArrayList(usermgr.RowFilterEntry).empty;
    errdefer {
        for (out.items) |*entry| entry.deinit(alloc);
        out.deinit(alloc);
    }
    var it = row_filter_value.object.iterator();
    while (it.next()) |entry| {
        const filter_json = try std.json.Stringify.valueAlloc(alloc, entry.value_ptr.*, .{});
        defer alloc.free(filter_json);
        try out.append(alloc, try usermgr.RowFilterEntry.initOwned(alloc, entry.key_ptr.*, filter_json));
    }
    return try out.toOwnedSlice(alloc);
}

fn applyAuthenticatedIdentityToJoinRequest(
    alloc: std.mem.Allocator,
    identity: AuthenticatedIdentity,
    join: *distributed_join.SupportedJoinRequest,
) !void {
    if (!permissionsAllow(identity.permissions, .table, join.right_table, .read)) return error.InvalidQueryRequest;

    const row_filter_json = try resolveEffectiveRowFilterJson(alloc, identity, join.right_table);
    defer if (row_filter_json) |value| alloc.free(value);
    if (row_filter_json) |value| {
        try distributed_join.applyRightTableRowFilterJson(alloc, join, value);
    }

    if (join.nested_join) |nested| {
        try applyAuthenticatedIdentityToJoinRequest(alloc, identity, nested);
    }
}

pub fn normalizeQueryEmbeddingOperationalError(err: anyerror) ?anyerror {
    return switch (err) {
        error.QueryEmbeddingInputTooLarge,
        error.QueryEmbeddingOverloaded,
        error.EmbedRateLimited,
        error.EmbedTransientFailure,
        error.Timeout,
        => err,
        error.EmbedRequestFailed,
        error.EmptyEmbeddingResponse,
        error.InvalidEmbeddingResponse,
        error.InvalidEmbeddingDimensions,
        error.SecretNotFound,
        => error.EmbedUpstreamFailure,
        error.ConnectionRefused,
        error.ConnectionResetByPeer,
        error.NetworkUnreachable,
        error.HostUnreachable,
        error.TemporaryNameServerFailure,
        error.NameServerFailure,
        error.ConnectionTimedOut,
        error.Canceled,
        => error.EmbedTransientFailure,
        else => null,
    };
}

fn normalizePublicQueryParseError(err: anyerror) anyerror {
    if (err == error.ModelNotFound or
        err == error.OutOfMemory or
        err == error.InvalidFilterQueryRequest or
        err == error.InvalidExclusionQueryRequest or
        err == error.UnsupportedFilterQueryRequest or
        err == error.UnsupportedExclusionQueryRequest)
    {
        return err;
    }
    return normalizeQueryEmbeddingOperationalError(err) orelse error.InvalidQueryRequest;
}

fn unsupportedPublicTableQueryDispatchError(alloc: std.mem.Allocator, body: []const u8) error{ InvalidQueryRequest, UnsupportedExactSort } {
    if (queryBodyHasSortPageControls(alloc, body)) return error.UnsupportedExactSort;
    return error.InvalidQueryRequest;
}

fn queryBodyHasSortPageControls(alloc: std.mem.Allocator, body: []const u8) bool {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{}) catch return false;
    defer parsed.deinit();
    const object = switch (parsed.value) {
        .object => |object| object,
        else => return false,
    };
    return object.get("order_by") != null or
        object.get("search_after") != null or
        object.get("search_before") != null;
}

fn writeMaybeAbsoluteUrl(writer: *std.Io.Writer, base_url: ?[]const u8, url: []const u8) !void {
    const base = base_url orelse return try std.json.Stringify.value(url, .{}, writer);
    if (base.len == 0 or !std.mem.startsWith(u8, url, "/")) return try std.json.Stringify.value(url, .{}, writer);
    var buf: [1024]u8 = undefined;
    var end = base.len;
    while (end > 0 and base[end - 1] == '/') end -= 1;
    const resolved = try std.fmt.bufPrint(&buf, "{s}{s}", .{ base[0..end], url });
    try std.json.Stringify.value(resolved, .{}, writer);
}

fn publicOperationTextResponse(
    alloc: std.mem.Allocator,
    status: u16,
    body: []const u8,
) !public_table_http.OwnedResponse {
    return .{
        .status = status,
        .body = try alloc.dupe(u8, body),
    };
}

fn publicOperationJsonResponse(
    alloc: std.mem.Allocator,
    status: u16,
    body: []const u8,
) !public_table_http.OwnedResponse {
    return .{
        .status = status,
        .body = try alloc.dupe(u8, body),
        .json = true,
    };
}

const ExtensionAgentRunRoute = struct {
    extension_name: []const u8,
    agent_name: []const u8,
    tail: []const u8,
};

fn parseExtensionAgentRunRoute(path: []const u8) ?ExtensionAgentRunRoute {
    if (!std.mem.startsWith(u8, path, routes.Routes.agents_v1_extensions_prefix)) return null;
    const rest = path[routes.Routes.agents_v1_extensions_prefix.len..];
    const extension_slash = std.mem.indexOfScalar(u8, rest, '/') orelse return null;
    const extension_name = rest[0..extension_slash];
    const agent_rest = rest[extension_slash + 1 ..];
    const agent_slash = std.mem.indexOfScalar(u8, agent_rest, '/') orelse return null;
    const agent_name = agent_rest[0..agent_slash];
    const tail = agent_rest[agent_slash + 1 ..];
    if (extension_name.len == 0 or agent_name.len == 0 or tail.len == 0) return null;
    return .{ .extension_name = extension_name, .agent_name = agent_name, .tail = tail };
}

fn extensionAgentUnsupportedRuntimeJsonAlloc(
    alloc: std.mem.Allocator,
    extension_name: []const u8,
    agent_name: []const u8,
    run_id: ?[]const u8,
) ![]u8 {
    var writer: std.Io.Writer.Allocating = .init(alloc);
    errdefer writer.deinit();
    try writer.writer.writeAll("{\"error\":\"extension agent runtime not implemented\",\"status\":\"unsupported_runtime\",\"extension\":");
    try std.json.Stringify.value(extension_name, .{}, &writer.writer);
    try writer.writer.writeAll(",\"agent\":");
    try std.json.Stringify.value(agent_name, .{}, &writer.writer);
    if (run_id) |id| {
        try writer.writer.writeAll(",\"runId\":");
        try std.json.Stringify.value(id, .{}, &writer.writer);
    }
    const descriptor_path = try std.fmt.allocPrint(alloc, "/ard/v1/resources/agents/extensions/{s}/{s}", .{ extension_name, agent_name });
    defer alloc.free(descriptor_path);
    try writer.writer.writeAll(",\"descriptor\":");
    try std.json.Stringify.value(descriptor_path, .{}, &writer.writer);
    try writer.writer.writeByte('}');
    return try writer.toOwnedSlice();
}

fn extensionAgentUnsupportedRuntimeEventAlloc(
    alloc: std.mem.Allocator,
    extension_name: []const u8,
    agent_name: []const u8,
    run_id: []const u8,
) ![]u8 {
    const data = try extensionAgentUnsupportedRuntimeJsonAlloc(alloc, extension_name, agent_name, run_id);
    defer alloc.free(data);
    return try std.fmt.allocPrint(alloc, "event: error\ndata: {s}\n\n", .{data});
}

pub fn makeSecretEntry(listed: common_secrets.ListedSecret) metadata_openapi.SecretEntry {
    return .{
        .key = listed.key,
        .status = mapSecretStatus(listed.status),
        .env_var = listed.env_var,
        .created_at = listed.created_at,
        .updated_at = listed.updated_at,
    };
}

pub fn makeSecretList(alloc: std.mem.Allocator, listed: []const common_secrets.ListedSecret) !metadata_openapi.SecretList {
    const entries = try alloc.alloc(metadata_openapi.SecretEntry, listed.len);
    for (listed, 0..) |item, i| {
        entries[i] = makeSecretEntry(item);
    }
    return .{ .secrets = entries };
}

fn mapSecretStatus(status: common_secrets.SecretStatus) metadata_openapi.SecretStatus {
    return switch (status) {
        .configured_file => .configured_file,
        .configured_env => .configured_env,
        .configured_both => .configured_both,
    };
}

pub const OwnedCreateUserRequest = struct {
    username: []u8,
    password: []u8,
    initial_policies: []usermgr.Permission,
    metadata_json: []u8,

    pub fn deinit(self: *OwnedCreateUserRequest, alloc: std.mem.Allocator) void {
        alloc.free(self.username);
        alloc.free(self.password);
        freePermissions(alloc, self.initial_policies);
        alloc.free(self.metadata_json);
        self.* = undefined;
    }
};

pub const OwnedCreateApiKeyRequest = struct {
    name: []u8,
    permissions: []usermgr.Permission,
    row_filter: []usermgr.RowFilterEntry,
    expires_at_ns: ?u64 = null,

    pub fn deinit(self: *OwnedCreateApiKeyRequest, alloc: std.mem.Allocator) void {
        alloc.free(self.name);
        freePermissions(alloc, self.permissions);
        freeRowFilters(alloc, self.row_filter);
        self.* = undefined;
    }
};

pub fn parseCreateUserRequest(alloc: std.mem.Allocator, body: []const u8, path_username: []const u8) !OwnedCreateUserRequest {
    var parsed = try usermgr_openapi.server.parseCreateUserBody(alloc, body);
    defer parsed.deinit();
    if (parsed.value.password.len == 0) return error.InvalidCreateUserRequest;

    const username = if (parsed.value.username) |username_value| blk: {
        if (username_value.len == 0) return error.InvalidCreateUserRequest;
        if (!std.mem.eql(u8, username_value, path_username)) return error.InvalidCreateUserRequest;
        break :blk try alloc.dupe(u8, username_value);
    } else try alloc.dupe(u8, path_username);
    errdefer alloc.free(username);

    const password = try alloc.dupe(u8, parsed.value.password);
    errdefer alloc.free(password);

    const initial_policies = try clonePermissionsFromOpenApi(alloc, parsed.value.initial_policies);
    errdefer freePermissions(alloc, initial_policies);
    const metadata_json = try normalizeMetadataFromOpenApi(alloc, parsed.value.metadata);
    errdefer alloc.free(metadata_json);

    return .{
        .username = username,
        .password = password,
        .initial_policies = initial_policies,
        .metadata_json = metadata_json,
    };
}

pub fn parsePasswordUpdateRequest(alloc: std.mem.Allocator, body: []const u8) ![]u8 {
    var parsed = try usermgr_openapi.server.parseUpdateUserPasswordBody(alloc, body);
    defer parsed.deinit();
    if (parsed.value.new_password.len == 0) return error.InvalidPasswordUpdateRequest;
    return try alloc.dupe(u8, parsed.value.new_password);
}

pub fn parseCreateApiKeyRequest(alloc: std.mem.Allocator, body: []const u8) !OwnedCreateApiKeyRequest {
    var parsed = try usermgr_openapi.server.parseCreateApiKeyBody(alloc, body);
    defer parsed.deinit();
    if (parsed.value.name.len == 0) return error.InvalidApiKeyRequest;
    const name = try alloc.dupe(u8, parsed.value.name);
    errdefer alloc.free(name);

    const permissions = try clonePermissionsFromOpenApi(alloc, parsed.value.permissions);
    errdefer freePermissions(alloc, permissions);

    const row_filter = try cloneRowFiltersFromOpenApi(alloc, parsed.value.row_filter);
    errdefer freeRowFilters(alloc, row_filter);

    const expires_at_ns = if (parsed.value.expires_in) |expires_in_value| blk: {
        if (expires_in_value.len == 0) break :blk null;
        break :blk nowNs() + try parseGoDurationNs(expires_in_value);
    } else null;

    return .{
        .name = name,
        .permissions = permissions,
        .row_filter = row_filter,
        .expires_at_ns = expires_at_ns,
    };
}

pub fn parsePermissionBody(alloc: std.mem.Allocator, body: []const u8) !usermgr.Permission {
    var parsed = try usermgr_openapi.server.parseAddPermissionToUserBody(alloc, body);
    defer parsed.deinit();
    return try permissionFromOpenApi(alloc, parsed.value);
}

pub fn parseRoleAssignmentBody(alloc: std.mem.Allocator, body: []const u8) ![]u8 {
    var parsed = try usermgr_openapi.server.parseAddRoleToUserBody(alloc, body);
    defer parsed.deinit();
    if (parsed.value.role.len == 0) return error.InvalidRole;
    return try alloc.dupe(u8, parsed.value.role);
}

fn clonePermissionsFromOpenApi(alloc: std.mem.Allocator, permissions: ?[]const usermgr_openapi.Permission) ![]usermgr.Permission {
    const source = permissions orelse return try alloc.alloc(usermgr.Permission, 0);
    const out = try alloc.alloc(usermgr.Permission, source.len);
    errdefer alloc.free(out);
    var filled: usize = 0;
    errdefer for (out[0..filled]) |*permission| permission.deinit(alloc);
    for (source, 0..) |item, i| {
        out[i] = try permissionFromOpenApi(alloc, item);
        filled += 1;
    }
    return out;
}

fn normalizeMetadataFromOpenApi(
    alloc: std.mem.Allocator,
    metadata: ?std.json.ArrayHashMap(std.json.Value),
) ![]u8 {
    const value = metadata orelse return try alloc.dupe(u8, "{}");
    return try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(value, .{})});
}

fn permissionFromOpenApi(alloc: std.mem.Allocator, value: usermgr_openapi.Permission) !usermgr.Permission {
    return try usermgr.Permission.initOwned(
        alloc,
        resourceTypeFromOpenApi(value.resource_type),
        value.resource,
        permissionTypeFromOpenApi(value.type),
    );
}

fn cloneRowFiltersFromOpenApi(
    alloc: std.mem.Allocator,
    row_filter: ?std.json.ArrayHashMap(std.json.Value),
) ![]usermgr.RowFilterEntry {
    const source = row_filter orelse return try alloc.alloc(usermgr.RowFilterEntry, 0);
    const out = try alloc.alloc(usermgr.RowFilterEntry, source.map.count());
    errdefer alloc.free(out);
    var it = source.map.iterator();
    var filled: usize = 0;
    errdefer for (out[0..filled]) |*entry| entry.deinit(alloc);
    while (it.next()) |entry| {
        const filter_json = try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(entry.value_ptr.*, .{})});
        defer alloc.free(filter_json);
        try validateAuthRowFilterJson(alloc, filter_json);
        out[filled] = try usermgr.RowFilterEntry.initOwned(alloc, entry.key_ptr.*, filter_json);
        filled += 1;
    }
    return out;
}

fn parseRemovePermissionFromUserParams(alloc: std.mem.Allocator, query: []const u8) !usermgr_openapi.server.RemovePermissionFromUserParams {
    const resource = (try parseSimpleQueryParamDecodedAlloc(alloc, query, "resource")) orelse return error.MissingResource;
    const resource_type = (try parseSimpleQueryParamDecodedAlloc(alloc, query, "resourceType")) orelse return error.MissingResourceType;
    _ = usermgr.ResourceType.fromSlice(resource_type) catch return error.InvalidResourceType;
    return .{
        .resource = resource,
        .resource_type = resource_type,
    };
}

fn parseRemoveRoleFromUserParams(alloc: std.mem.Allocator, query: []const u8) !usermgr_openapi.server.RemoveRoleFromUserParams {
    const role = (try parseSimpleQueryParamDecodedAlloc(alloc, query, "role")) orelse return error.MissingRole;
    if (role.len == 0) return error.MissingRole;
    return .{ .role = role };
}

const ListBackupsParams = struct {
    location: []const u8,
    connection: ?[]const u8,
    limit: usize,
    cursor: ?[]const u8,
};

fn parseListBackupsParams(alloc: std.mem.Allocator, query: []const u8) !ListBackupsParams {
    const raw_limit = try parseSimpleQueryParamDecodedAlloc(alloc, query, "limit");
    const limit = if (raw_limit) |value| try std.fmt.parseInt(usize, value, 10) else backups_api.default_backup_list_limit;
    if (limit == 0 or limit > backups_api.max_backup_list_limit) return error.InvalidBackupListLimit;
    const cursor = try parseSimpleQueryParamDecodedAlloc(alloc, query, "cursor");
    if (cursor) |value| try backups_api.validateBackupId(value);
    return .{
        .location = (try parseSimpleQueryParamDecodedAlloc(alloc, query, "location")) orelse return error.MissingLocation,
        .connection = try parseSimpleQueryParamDecodedAlloc(alloc, query, "connection"),
        .limit = limit,
        .cursor = cursor,
    };
}

fn parseRestoreJobListOptions(alloc: std.mem.Allocator, query: []const u8) !ApiHttpServer.RestoreJobListOptions {
    const raw_limit = try parseSimpleQueryParamDecodedAlloc(alloc, query, "limit");
    const limit = if (raw_limit) |value| try std.fmt.parseInt(usize, value, 10) else 50;
    if (limit == 0 or limit > 100) return error.InvalidRestoreJobListLimit;
    const raw_cursor = try parseSimpleQueryParamDecodedAlloc(alloc, query, "cursor");
    const cursor = if (raw_cursor) |value| blk: {
        const parsed = try std.fmt.parseUnsigned(u64, value, 10);
        if (parsed == 0) return error.InvalidRestoreJobListCursor;
        break :blk parsed;
    } else null;
    const raw_phase = try parseSimpleQueryParamDecodedAlloc(alloc, query, "phase");
    const phase = if (raw_phase) |value| std.meta.stringToEnum(restore_jobs.Phase, value) orelse return error.InvalidRestoreJobListPhase else null;
    const raw_scope = try parseSimpleQueryParamDecodedAlloc(alloc, query, "scope");
    const scope = if (raw_scope) |value| std.meta.stringToEnum(restore_jobs.Scope, value) orelse return error.InvalidRestoreJobListScope else null;
    return .{ .limit = limit, .cursor = cursor, .phase = phase, .scope = scope };
}

fn parseListTablesParams(alloc: std.mem.Allocator, query: []const u8) !metadata_openapi.server.ListTablesParams {
    return .{
        .prefix = try parseSimpleQueryParamDecodedAlloc(alloc, query, "prefix"),
        .pattern = try parseSimpleQueryParamDecodedAlloc(alloc, query, "pattern"),
    };
}

fn resourceTypeFromOpenApi(value: usermgr_openapi.ResourceType) usermgr.ResourceType {
    return switch (value) {
        .table => .table,
        .user => .user,
        .inference => .inference,
        .@"*" => .@"*",
    };
}

fn permissionTypeFromOpenApi(value: usermgr_openapi.PermissionType) usermgr.PermissionType {
    return switch (value) {
        .read => .read,
        .write => .write,
        .admin => .admin,
    };
}

fn resourceTypeToOpenApi(value: usermgr.ResourceType) usermgr_openapi.ResourceType {
    return switch (value) {
        .table => .table,
        .user => .user,
        .inference => .inference,
        .@"*" => .@"*",
    };
}

fn permissionTypeToOpenApi(value: usermgr.PermissionType) usermgr_openapi.PermissionType {
    return switch (value) {
        .read => .read,
        .write => .write,
        .admin => .admin,
    };
}

pub fn clonePermissionsToOpenApi(alloc: std.mem.Allocator, permissions: []const usermgr.Permission) ![]usermgr_openapi.Permission {
    const out = try alloc.alloc(usermgr_openapi.Permission, permissions.len);
    for (permissions, 0..) |permission, i| {
        out[i] = .{
            .resource = permission.resource,
            .resource_type = resourceTypeToOpenApi(permission.resource_type),
            .type = permissionTypeToOpenApi(permission.type),
        };
    }
    return out;
}

fn rowFilterMapToOpenApi(
    alloc: std.mem.Allocator,
    row_filters: []const usermgr.RowFilterEntry,
) !std.json.ArrayHashMap(std.json.Value) {
    var out = std.json.ArrayHashMap(std.json.Value){};
    for (row_filters) |entry| {
        const filter_value = try parseOwnedJsonValueAlloc(alloc, entry.filter);
        try out.map.put(alloc, entry.table, filter_value);
    }
    return out;
}

pub fn rowFilterEntryToOpenApi(
    alloc: std.mem.Allocator,
    entry: usermgr.RowFilterEntry,
) !usermgr_openapi.RowFilterEntry {
    const parsed_filter = try parseOwnedJsonObjectMapAlloc(alloc, entry.filter);
    return .{
        .table = entry.table,
        .filter = parsed_filter,
    };
}

pub fn apiKeyToOpenApi(
    alloc: std.mem.Allocator,
    api_key: usermgr.ApiKey,
) !usermgr_openapi.ApiKey {
    return .{
        .key_id = api_key.key_id,
        .name = api_key.name,
        .username = api_key.username,
        .permissions = if (api_key.permissions.len > 0) try clonePermissionsToOpenApi(alloc, api_key.permissions) else null,
        .row_filter = if (api_key.row_filter.len > 0) try rowFilterMapToOpenApi(alloc, api_key.row_filter) else null,
        .created_at = try formatTimestampOwned(alloc, api_key.created_at_ns),
        .expires_at = if (api_key.expires_at_ns) |value| try formatTimestampOwned(alloc, value) else null,
    };
}

pub fn createdApiKeyToOpenApi(
    alloc: std.mem.Allocator,
    created: usermgr.CreatedApiKey,
) !usermgr_openapi.ApiKeyWithSecret {
    const base = try apiKeyToOpenApi(alloc, created.key);
    return .{
        .key_id = base.key_id,
        .name = base.name,
        .username = base.username,
        .permissions = base.permissions,
        .row_filter = base.row_filter,
        .created_at = base.created_at,
        .expires_at = base.expires_at,
        .key_secret = created.key_secret,
        .encoded = created.encoded,
    };
}

fn parseGoDurationNs(raw: []const u8) !u64 {
    if (raw.len == 0) return error.InvalidDuration;
    var i: usize = 0;
    var total: u64 = 0;
    while (i < raw.len) {
        const start = i;
        while (i < raw.len and std.ascii.isDigit(raw[i])) : (i += 1) {}
        if (i == start) return error.InvalidDuration;
        const value = try std.fmt.parseUnsigned(u64, raw[start..i], 10);
        const unit: u64 = if (std.mem.startsWith(u8, raw[i..], "ns")) blk: {
            i += 2;
            break :blk @as(u64, 1);
        } else if (std.mem.startsWith(u8, raw[i..], "us")) blk: {
            i += 2;
            break :blk @as(u64, std.time.ns_per_us);
        } else if (std.mem.startsWith(u8, raw[i..], "ms")) blk: {
            i += 2;
            break :blk @as(u64, std.time.ns_per_ms);
        } else if (i < raw.len and raw[i] == 's') blk: {
            i += 1;
            break :blk @as(u64, std.time.ns_per_s);
        } else if (i < raw.len and raw[i] == 'm') blk: {
            i += 1;
            break :blk @as(u64, std.time.ns_per_min);
        } else if (i < raw.len and raw[i] == 'h') blk: {
            i += 1;
            break :blk @as(u64, std.time.ns_per_hour);
        } else if (i < raw.len and raw[i] == 'd') blk: {
            i += 1;
            break :blk @as(u64, 24 * std.time.ns_per_hour);
        } else return error.InvalidDuration;
        total += value * unit;
    }
    return total;
}

fn formatTimestampOwned(alloc: std.mem.Allocator, ns: u64) ![]u8 {
    const epoch_seconds = std.time.epoch.EpochSeconds{
        .secs = @divFloor(ns, std.time.ns_per_s),
    };
    const year_day = epoch_seconds.getEpochDay().calculateYearDay();
    const month_day = year_day.calculateMonthDay();
    const day_seconds = epoch_seconds.getDaySeconds();
    return try std.fmt.allocPrint(alloc, "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z", .{
        year_day.year,
        month_day.month.numeric(),
        month_day.day_index + 1,
        day_seconds.getHoursIntoDay(),
        day_seconds.getMinutesIntoHour(),
        day_seconds.getSecondsIntoMinute(),
    });
}

fn nowNs() u64 {
    return platform_time.realtimeNs();
}

pub fn freePermissions(alloc: std.mem.Allocator, permissions: []const usermgr.Permission) void {
    for (permissions) |permission| {
        var owned = permission;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(permissions));
}

fn clonePermissions(alloc: std.mem.Allocator, permissions: []const usermgr.Permission) ![]usermgr.Permission {
    var out = std.ArrayList(usermgr.Permission).empty;
    errdefer {
        for (out.items) |*permission| permission.deinit(alloc);
        out.deinit(alloc);
    }
    for (permissions) |permission| {
        var cloned = try usermgr.Permission.initOwned(
            alloc,
            permission.resource_type,
            permission.resource,
            permission.type,
        );
        var cloned_owned = true;
        errdefer if (cloned_owned) cloned.deinit(alloc);
        try out.append(alloc, cloned);
        cloned_owned = false;
    }
    return try out.toOwnedSlice(alloc);
}

pub fn freeRowFilters(alloc: std.mem.Allocator, row_filters: []const usermgr.RowFilterEntry) void {
    for (row_filters) |entry| {
        var owned = entry;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(row_filters));
}

fn cloneRowFilters(alloc: std.mem.Allocator, row_filters: []const usermgr.RowFilterEntry) ![]usermgr.RowFilterEntry {
    var out = std.ArrayList(usermgr.RowFilterEntry).empty;
    errdefer {
        for (out.items) |*entry| entry.deinit(alloc);
        out.deinit(alloc);
    }
    for (row_filters) |entry| {
        var cloned = try usermgr.RowFilterEntry.initOwned(alloc, entry.table, entry.filter);
        var cloned_owned = true;
        errdefer if (cloned_owned) cloned.deinit(alloc);
        try out.append(alloc, cloned);
        cloned_owned = false;
    }
    return try out.toOwnedSlice(alloc);
}

fn cloneAuthenticatedIdentity(
    alloc: std.mem.Allocator,
    username: []const u8,
    permissions: []const usermgr.Permission,
    row_filter: []const usermgr.RowFilterEntry,
    metadata_json: []const u8,
    roles: []const []const u8,
) !AuthenticatedIdentity {
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, username),
        .metadata_json = &.{},
    };
    errdefer identity.deinit(alloc);
    identity.permissions = try clonePermissions(alloc, permissions);
    identity.row_filter = try cloneRowFilters(alloc, row_filter);
    identity.metadata_json = try alloc.dupe(u8, if (metadata_json.len > 0) metadata_json else "{}");
    identity.roles = try cloneOwnedStrings(alloc, roles);
    return identity;
}

pub fn freeAuthSubjects(alloc: std.mem.Allocator, subjects: []const usermgr.AuthSubjectEntry) void {
    for (subjects) |entry| {
        var owned = entry;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(subjects));
}

pub const AuthSubjectResponse = struct {
    subject: []const u8,
    kind: []const u8,
};

pub fn authSubjectsToResponse(
    alloc: std.mem.Allocator,
    subjects: []const usermgr.AuthSubjectEntry,
) ![]const AuthSubjectResponse {
    const out = try alloc.alloc(AuthSubjectResponse, subjects.len);
    for (subjects, 0..) |entry, i| {
        out[i] = .{
            .subject = entry.subject,
            .kind = entry.kind.slice(),
        };
    }
    return out;
}

pub fn effectiveRowFilterJson(identity: ?AuthenticatedIdentity, table_name: []const u8) ?[]const u8 {
    const row_filters = if (identity) |value| value.row_filter else return null;
    for (row_filters) |entry| {
        if (std.mem.eql(u8, entry.table, table_name)) {
            if (std.mem.eql(u8, entry.filter, "null")) return null;
            return entry.filter;
        }
    }
    for (row_filters) |entry| {
        if (std.mem.eql(u8, entry.table, "*")) {
            if (std.mem.eql(u8, entry.filter, "null")) return null;
            return entry.filter;
        }
    }
    return null;
}

pub fn resolveEffectiveRowFilterJson(
    alloc: std.mem.Allocator,
    identity: ?AuthenticatedIdentity,
    table_name: []const u8,
) !?[]u8 {
    const raw = effectiveRowFilterJson(identity, table_name) orelse return null;
    const active_identity = identity orelse return try alloc.dupe(u8, raw);
    return try resolveAuthRowFilterJson(alloc, active_identity, raw);
}

pub fn resolveAuthRowFilterJson(
    alloc: std.mem.Allocator,
    identity: AuthenticatedIdentity,
    filter_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, filter_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    try validateAuthRowFilterValue(parsed.value);
    var remaining_nodes: usize = auth_filter_max_tree_nodes;

    var parsed_metadata: ?std.json.Parsed(std.json.Value) = null;
    defer if (parsed_metadata) |*metadata| metadata.deinit();
    if (authFilterUsesMetadataReference(parsed.value)) {
        parsed_metadata = std.json.parseFromSlice(
            std.json.Value,
            alloc,
            if (identity.metadata_json.len > 0) identity.metadata_json else "{}",
            .{},
        ) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return try alloc.dupe(u8, "{\"match_none\":{}}"),
        };
    }
    const context = AuthRowFilterResolveContext{
        .identity = identity,
        .metadata = if (parsed_metadata) |metadata| metadata.value else null,
    };
    var resolved = resolveAuthRowFilterValue(
        alloc,
        context,
        parsed.value,
        .filter,
        &remaining_nodes,
    ) catch |err| switch (err) {
        // Identity metadata is allowed to vary independently of policy
        // admission. Missing or type-incompatible values must deny the whole
        // policy, never turn a protected read into a server error or weaken a
        // negative branch.
        error.AuthRowFilterNoMatch => return try alloc.dupe(u8, "{\"match_none\":{}}"),
        else => return err,
    };
    defer json_helpers.deinitJsonValue(alloc, &resolved);
    return try json_helpers.stringifyJsonValueAlloc(alloc, resolved);
}

pub fn validateAuthRowFilterJson(
    alloc: std.mem.Allocator,
    filter_json: []const u8,
) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, filter_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    try validateAuthRowFilterValue(parsed.value);

    // Compile a type-correct representative of the policy before it can be
    // persisted. Dynamic auth references are restricted to the documented
    // scalar `term` and array `terms` positions; every other node is validated
    // by the same prepared Zig filter plan used during execution.
    var materialized = try materializeAuthFilterTemplateValue(
        alloc,
        parsed.value,
        .filter,
    );
    defer json_helpers.deinitJsonValue(alloc, &materialized);
    var prepared = try search_pattern_filter.PreparedPatternFilter.initValue(
        alloc,
        materialized,
    );
    prepared.deinit();
}

const AuthFilterTemplateExpectation = enum {
    filter,
    term_body,
    terms_body,
    scalar,
    array,
    static,
};

fn authFilterObjectChildExpectation(
    expectation: AuthFilterTemplateExpectation,
    object: std.json.ObjectMap,
    key: []const u8,
) !AuthFilterTemplateExpectation {
    return switch (expectation) {
        .filter => if (std.mem.eql(u8, key, "term"))
            .term_body
        else if (std.mem.eql(u8, key, "terms"))
            .terms_body
        else
            .filter,
        .term_body => if (object.count() == 1 or
            std.mem.eql(u8, key, "term") or
            std.mem.eql(u8, key, "value"))
            .scalar
        else
            .static,
        .terms_body => if (object.count() == 1 or
            std.mem.eql(u8, key, "terms") or
            std.mem.eql(u8, key, "values"))
            .array
        else
            .static,
        .static => .static,
        .scalar, .array => error.InvalidQueryRequest,
    };
}

fn authFilterArrayChildExpectation(
    expectation: AuthFilterTemplateExpectation,
) !AuthFilterTemplateExpectation {
    return switch (expectation) {
        .filter => .filter,
        .array, .static => .static,
        .term_body, .terms_body, .scalar => error.InvalidQueryRequest,
    };
}

fn materializeAuthFilterTemplateValue(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    expectation: AuthFilterTemplateExpectation,
) !std.json.Value {
    return switch (value) {
        .object => |object| blk: {
            if (object.get("$auth")) |auth_ref| {
                if (object.count() != 1 or
                    (expectation != .scalar and expectation != .array))
                {
                    return error.InvalidQueryRequest;
                }
                const path = if (auth_ref == .string)
                    auth_ref.string
                else
                    return error.InvalidQueryRequest;
                if (!isSupportedAuthPath(path)) return error.InvalidQueryRequest;
                if (std.mem.eql(u8, path, "roles") and expectation != .array) {
                    return error.InvalidQueryRequest;
                }
                if (std.mem.eql(u8, path, "username") and expectation != .scalar) {
                    return error.InvalidQueryRequest;
                }
                if (expectation == .scalar) {
                    break :blk .{ .string = try alloc.dupe(u8, "__auth_validation__") };
                }
                var items = std.json.Array.init(alloc);
                errdefer {
                    for (items.items) |*item| json_helpers.deinitJsonValue(alloc, item);
                    items.deinit();
                }
                const sentinel = try alloc.dupe(u8, "__auth_validation__");
                errdefer alloc.free(sentinel);
                try items.append(.{ .string = sentinel });
                break :blk .{ .array = items };
            }
            if (expectation == .scalar or expectation == .array) {
                return error.InvalidQueryRequest;
            }

            var out = std.json.ObjectMap.empty;
            errdefer {
                var it = out.iterator();
                while (it.next()) |entry| {
                    alloc.free(@constCast(entry.key_ptr.*));
                    json_helpers.deinitJsonValue(alloc, entry.value_ptr);
                }
                out.deinit(alloc);
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                const child_expectation = try authFilterObjectChildExpectation(
                    expectation,
                    object,
                    entry.key_ptr.*,
                );
                const key = try alloc.dupe(u8, entry.key_ptr.*);
                var key_transferred = false;
                errdefer if (!key_transferred) alloc.free(key);
                var child = try materializeAuthFilterTemplateValue(
                    alloc,
                    entry.value_ptr.*,
                    child_expectation,
                );
                var child_transferred = false;
                errdefer if (!child_transferred) {
                    json_helpers.deinitJsonValue(alloc, &child);
                };
                try out.put(alloc, key, child);
                key_transferred = true;
                child_transferred = true;
            }
            break :blk .{ .object = out };
        },
        .array => |array| blk: {
            const child_expectation = try authFilterArrayChildExpectation(expectation);
            var out = std.json.Array.init(alloc);
            errdefer {
                for (out.items) |*item| json_helpers.deinitJsonValue(alloc, item);
                out.deinit();
            }
            for (array.items) |item| {
                var child = try materializeAuthFilterTemplateValue(
                    alloc,
                    item,
                    child_expectation,
                );
                var child_transferred = false;
                errdefer if (!child_transferred) {
                    json_helpers.deinitJsonValue(alloc, &child);
                };
                try out.append(child);
                child_transferred = true;
            }
            break :blk .{ .array = out };
        },
        else => switch (expectation) {
            .array, .term_body, .terms_body => error.InvalidQueryRequest,
            .filter, .scalar, .static => try json_helpers.cloneJsonValue(alloc, value),
        },
    };
}

const auth_filter_max_tree_depth: u8 = 64;
const auth_filter_max_tree_nodes: usize = 16_384;

fn authFilterUsesMetadataReference(value: std.json.Value) bool {
    return switch (value) {
        .object => |object| blk: {
            if (object.get("$auth")) |auth_ref| {
                break :blk auth_ref == .string and
                    std.mem.startsWith(u8, auth_ref.string, "metadata.");
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                if (authFilterUsesMetadataReference(entry.value_ptr.*)) {
                    break :blk true;
                }
            }
            break :blk false;
        },
        .array => |array| blk: {
            for (array.items) |item| {
                if (authFilterUsesMetadataReference(item)) break :blk true;
            }
            break :blk false;
        },
        else => false,
    };
}

fn validateAuthRowFilterValue(value: std.json.Value) !void {
    var remaining_nodes: usize = auth_filter_max_tree_nodes;
    return try validateAuthRowFilterValueBounded(value, 0, &remaining_nodes);
}

fn validateAuthRowFilterValueBounded(
    value: std.json.Value,
    depth: u8,
    remaining_nodes: *usize,
) !void {
    if (depth >= auth_filter_max_tree_depth or remaining_nodes.* == 0) {
        return error.InvalidQueryRequest;
    }
    remaining_nodes.* -= 1;
    switch (value) {
        .object => |object| {
            if (object.get("$auth")) |auth_ref| {
                if (object.count() != 1) return error.InvalidQueryRequest;
                const path = if (auth_ref == .string) auth_ref.string else return error.InvalidQueryRequest;
                if (!isSupportedAuthPath(path)) return error.InvalidQueryRequest;
                return;
            }

            var it = object.iterator();
            while (it.next()) |entry| {
                try validateAuthRowFilterValueBounded(
                    entry.value_ptr.*,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        .array => |array| {
            for (array.items) |item| {
                try validateAuthRowFilterValueBounded(
                    item,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        else => {},
    }
}

const AuthRowFilterResolveContext = struct {
    identity: AuthenticatedIdentity,
    metadata: ?std.json.Value,
};

fn resolveAuthRowFilterValue(
    alloc: std.mem.Allocator,
    context: AuthRowFilterResolveContext,
    value: std.json.Value,
    expectation: AuthFilterTemplateExpectation,
    remaining_nodes: *usize,
) !std.json.Value {
    return switch (value) {
        .object => |object| blk: {
            if (object.get("$auth")) |auth_ref| {
                if (object.count() != 1 or
                    (expectation != .scalar and expectation != .array))
                {
                    return error.InvalidQueryRequest;
                }
                const path = if (auth_ref == .string) auth_ref.string else return error.InvalidQueryRequest;
                if (!isSupportedAuthPath(path)) return error.InvalidQueryRequest;
                if (std.mem.eql(u8, path, "roles") and expectation != .array) {
                    return error.InvalidQueryRequest;
                }
                if (std.mem.eql(u8, path, "username") and expectation != .scalar) {
                    return error.InvalidQueryRequest;
                }
                const auth_value = authContextJsonValueBounded(
                    alloc,
                    context,
                    path,
                    remaining_nodes.*,
                ) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => return error.AuthRowFilterNoMatch,
                };
                var resolved = auth_value.value;
                errdefer json_helpers.deinitJsonValue(alloc, &resolved);
                if (!authFilterValueMatchesExpectation(resolved, expectation)) {
                    return error.AuthRowFilterNoMatch;
                }
                remaining_nodes.* -= auth_value.node_count;
                break :blk resolved;
            }
            if (remaining_nodes.* == 0) return error.AuthRowFilterNoMatch;
            remaining_nodes.* -= 1;
            if (expectation == .scalar or expectation == .array) {
                return error.InvalidQueryRequest;
            }

            var out = std.json.ObjectMap.empty;
            errdefer {
                var it = out.iterator();
                while (it.next()) |entry| {
                    alloc.free(@constCast(entry.key_ptr.*));
                    json_helpers.deinitJsonValue(alloc, entry.value_ptr);
                }
                out.deinit(alloc);
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                const child_expectation = try authFilterObjectChildExpectation(
                    expectation,
                    object,
                    entry.key_ptr.*,
                );
                const key = try alloc.dupe(u8, entry.key_ptr.*);
                var key_transferred = false;
                errdefer if (!key_transferred) alloc.free(key);
                var resolved = try resolveAuthRowFilterValue(
                    alloc,
                    context,
                    entry.value_ptr.*,
                    child_expectation,
                    remaining_nodes,
                );
                var value_transferred = false;
                errdefer if (!value_transferred) json_helpers.deinitJsonValue(alloc, &resolved);
                try out.put(alloc, key, resolved);
                key_transferred = true;
                value_transferred = true;
            }
            break :blk .{ .object = out };
        },
        .array => |array| blk: {
            if (remaining_nodes.* == 0) return error.AuthRowFilterNoMatch;
            remaining_nodes.* -= 1;
            const child_expectation = try authFilterArrayChildExpectation(expectation);
            var out = std.json.Array.init(alloc);
            errdefer {
                for (out.items) |*item| json_helpers.deinitJsonValue(alloc, item);
                out.deinit();
            }
            for (array.items) |item| {
                var resolved = try resolveAuthRowFilterValue(
                    alloc,
                    context,
                    item,
                    child_expectation,
                    remaining_nodes,
                );
                var value_transferred = false;
                errdefer if (!value_transferred) json_helpers.deinitJsonValue(alloc, &resolved);
                try out.append(resolved);
                value_transferred = true;
            }
            break :blk .{ .array = out };
        },
        else => blk: {
            if (remaining_nodes.* == 0) return error.AuthRowFilterNoMatch;
            remaining_nodes.* -= 1;
            break :blk switch (expectation) {
                .array, .term_body, .terms_body => error.InvalidQueryRequest,
                .filter, .scalar, .static => try json_helpers.cloneJsonValue(alloc, value),
            };
        },
    };
}

fn authFilterValueMatchesExpectation(
    value: std.json.Value,
    expectation: AuthFilterTemplateExpectation,
) bool {
    return switch (expectation) {
        .scalar => switch (value) {
            .string, .integer, .float, .number_string, .bool, .null => true,
            else => false,
        },
        .array => switch (value) {
            .array => |array| blk: {
                if (array.items.len == 0 or
                    array.items.len > auth_filter_max_tree_nodes)
                {
                    break :blk false;
                }
                for (array.items) |item| {
                    if (!authFilterValueMatchesExpectation(item, .scalar)) {
                        break :blk false;
                    }
                }
                break :blk true;
            },
            else => false,
        },
        else => false,
    };
}

const BoundedAuthContextJsonValue = struct {
    value: std.json.Value,
    node_count: usize,
};

fn authContextJsonValueBounded(
    alloc: std.mem.Allocator,
    context: AuthRowFilterResolveContext,
    path: []const u8,
    max_nodes: usize,
) !BoundedAuthContextJsonValue {
    if (max_nodes == 0) return error.InvalidQueryRequest;
    if (isSupportedAuthPath(path)) {
        if (std.mem.eql(u8, path, "username")) {
            return .{
                .value = .{ .string = try alloc.dupe(u8, context.identity.username) },
                .node_count = 1,
            };
        }
        if (std.mem.eql(u8, path, "roles")) {
            if (context.identity.roles.len == 0 or context.identity.roles.len >= max_nodes) {
                return error.InvalidQueryRequest;
            }
            return .{
                .value = try rolesAuthJsonValue(alloc, context.identity.roles),
                .node_count = 1 + context.identity.roles.len,
            };
        }
        return try metadataAuthJsonValueBounded(
            alloc,
            context.metadata orelse return error.InvalidQueryRequest,
            path["metadata.".len..],
            max_nodes,
        );
    }
    return error.InvalidQueryRequest;
}

fn isSupportedAuthPath(path: []const u8) bool {
    if (std.mem.eql(u8, path, "username")) return true;
    if (std.mem.eql(u8, path, "roles")) return true;
    if (!std.mem.startsWith(u8, path, "metadata.")) return false;
    var segments = std.mem.splitScalar(u8, path["metadata.".len..], '.');
    var seen = false;
    while (segments.next()) |segment| {
        if (segment.len == 0) return false;
        seen = true;
    }
    return seen;
}

fn rolesAuthJsonValue(
    alloc: std.mem.Allocator,
    roles: []const []const u8,
) !std.json.Value {
    var out = std.json.Array.init(alloc);
    errdefer {
        for (out.items) |*item| json_helpers.deinitJsonValue(alloc, item);
        out.deinit();
    }
    for (roles) |role| {
        try out.append(.{ .string = try alloc.dupe(u8, role) });
    }
    return .{ .array = out };
}

fn metadataAuthJsonValueBounded(
    alloc: std.mem.Allocator,
    metadata: std.json.Value,
    path: []const u8,
    max_nodes: usize,
) !BoundedAuthContextJsonValue {
    var current = metadata;
    var segments = std.mem.splitScalar(u8, path, '.');
    while (segments.next()) |segment| {
        if (segment.len == 0 or current != .object) return error.InvalidQueryRequest;
        current = current.object.get(segment) orelse return error.InvalidQueryRequest;
    }
    var remaining_nodes = max_nodes;
    try consumeAuthContextJsonBudget(current, 0, &remaining_nodes);
    return .{
        .value = try json_helpers.cloneJsonValue(alloc, current),
        .node_count = max_nodes - remaining_nodes,
    };
}

fn consumeAuthContextJsonBudget(
    value: std.json.Value,
    depth: u8,
    remaining_nodes: *usize,
) !void {
    if (depth >= auth_filter_max_tree_depth or remaining_nodes.* == 0) {
        return error.InvalidQueryRequest;
    }
    remaining_nodes.* -= 1;
    switch (value) {
        .object => |object| {
            var it = object.iterator();
            while (it.next()) |entry| {
                try consumeAuthContextJsonBudget(
                    entry.value_ptr.*,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        .array => |array| {
            for (array.items) |item| {
                try consumeAuthContextJsonBudget(
                    item,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        else => {},
    }
}

test "auth row filter resolver expands username references" {
    const alloc = std.testing.allocator;
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
    };
    defer identity.deinit(alloc);

    const resolved = try resolveAuthRowFilterJson(
        alloc,
        identity,
        "{\"term\":{\"owner\":{\"$auth\":\"username\"}}}",
    );
    defer alloc.free(resolved);

