    return json_helpers.extractJsonPathValue(source, path);
}

pub fn freeApiKeys(alloc: std.mem.Allocator, api_keys: []const usermgr.ApiKey) void {
    for (api_keys) |api_key| {
        var owned = api_key;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(api_keys));
}

pub const ListedUserEntry = struct { username: []const u8 };

pub fn makeListedUsers(alloc: std.mem.Allocator, users: []const []const u8) ![]ListedUserEntry {
    const listed = try alloc.alloc(ListedUserEntry, users.len);
    for (users, 0..) |username, i| {
        listed[i] = .{ .username = username };
    }
    return listed;
}

pub fn userToOpenApi(alloc: std.mem.Allocator, user: usermgr.User) !usermgr_openapi.User {
    return .{
        .username = user.username,
        .password_hash = user.password_hash,
        .metadata = if (user.metadata_json.len > 0) try parseOwnedJsonObjectMapAlloc(alloc, user.metadata_json) else null,
    };
}

pub fn makeCurrentUserResponse(
    alloc: std.mem.Allocator,
    username: []const u8,
    permissions: []const usermgr.Permission,
    metadata_json: []const u8,
) !struct {
    username: []const u8,
    permissions: []const usermgr_openapi.Permission,
    metadata: ?std.json.ArrayHashMap(std.json.Value) = null,
} {
    const generated_permissions = try clonePermissionsToOpenApi(alloc, permissions);
    return .{
        .username = username,
        .permissions = generated_permissions,
        .metadata = if (metadata_json.len > 0) try parseOwnedJsonObjectMapAlloc(alloc, metadata_json) else null,
    };
}

fn restoreIdempotencyNamespaceAlloc(
    alloc: std.mem.Allocator,
    principal: ?[]const u8,
    scope: restore_jobs.Scope,
    table_name: ?[]const u8,
) ![]u8 {
    const canonical = try std.json.Stringify.valueAlloc(alloc, .{
        .principal = principal orelse "anonymous",
        .scope = scope,
        .table_name = table_name,
    }, .{ .emit_null_optional_fields = false });
    defer alloc.free(canonical);
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(canonical, &digest, .{});
    const hex = std.fmt.bytesToHex(digest, .lower);
    return try alloc.dupe(u8, &hex);
}

fn metadataAccessFailure(err: anyerror) error{ NotLeader, InternalFailure } {
    if (metadata_authority.isRetryableError(err)) return error.NotLeader;
    return error.InternalFailure;
}

pub fn shouldRetryMetadataMutation(err: anyerror, elapsed_ns: u64, timeout_ns: u64) bool {
    return elapsed_ns < timeout_ns and
        (err == error.UnexpectedHttpStatus or metadata_authority.isRetryableError(err));
}

test "public metadata mutation retries transient authority loss only within its deadline" {
    const timeout_ns = default_metadata_mutation_retry_timeout_ns;
    try std.testing.expect(shouldRetryMetadataMutation(error.NotLeader, timeout_ns - 1, timeout_ns));
    try std.testing.expect(shouldRetryMetadataMutation(error.ProposalDropped, 0, timeout_ns));
    try std.testing.expect(shouldRetryMetadataMutation(error.UnexpectedHttpStatus, 0, timeout_ns));
    try std.testing.expect(!shouldRetryMetadataMutation(error.NotLeader, timeout_ns, timeout_ns));
    try std.testing.expect(!shouldRetryMetadataMutation(error.InvalidArguments, 0, timeout_ns));

    const bounded_attempts = MetadataMutationRetryPolicy{ .max_attempts = 3 };
    try std.testing.expect(bounded_attempts.shouldRetry(error.NotLeader, 0, 2));
    try std.testing.expect(!bounded_attempts.shouldRetry(error.NotLeader, 0, 3));
}

pub fn buildLocalSchemaUpdateStatus(alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) !struct {
    name: []const u8,
    schema: schema_openapi.TableSchema,
} {
    return .{
        .name = table_name,
        .schema = try std.json.parseFromSliceLeaky(schema_openapi.TableSchema, alloc, schema_json, .{
            .allocate = .alloc_always,
        }),
    };
}

pub fn stripApiPrefix(path: []const u8) []const u8 {
    const prefix = "/db/v1";
    if (std.mem.startsWith(u8, path, prefix)) {
        const rest = path[prefix.len..];
        // "/db/v1" alone or "/db/v1/" → "/"
        if (rest.len == 0) return "/";
        return rest;
    }
    return path;
}

const UriParts = struct { path: []const u8, query: []const u8 };

fn splitTarget(target: []const u8) UriParts {
    const query_index = std.mem.indexOfScalar(u8, target, '?') orelse return .{
        .path = stripApiPrefix(target),
        .query = "",
    };
    return .{
        .path = stripApiPrefix(target[0..query_index]),
        .query = target[query_index + 1 ..],
    };
}

fn rawPathOnly(target: []const u8) []const u8 {
    const query_index = std.mem.indexOfScalar(u8, target, '?') orelse return target;
    return target[0..query_index];
}

fn decodeRequestPathParamAlloc(alloc: std.mem.Allocator, encoded: []const u8) ![]u8 {
    return http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded) catch |err| switch (err) {
        error.InvalidArgument => return error.InvalidPathParameter,
        else => return err,
    };
}

fn parseSimpleQueryParam(query: []const u8, key: []const u8) ?[]const u8 {
    if (query.len == 0) return null;
    var it = std.mem.splitScalar(u8, query, '&');
    while (it.next()) |part| {
        if (!std.mem.startsWith(u8, part, key)) continue;
        if (part.len <= key.len or part[key.len] != '=') continue;
        return part[key.len + 1 ..];
    }
    return null;
}

fn parseSimpleQueryParamDecodedAlloc(alloc: std.mem.Allocator, query: []const u8, key: []const u8) !?[]u8 {
    const raw = parseSimpleQueryParam(query, key) orelse return null;
    return try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, raw);
}

pub fn parseLookupReadConsistency(query: []const u8) !raft_mod.ReadConsistency {
    const value = parseSimpleQueryParam(query, "consistency") orelse
        parseSimpleQueryParam(query, "read_consistency") orelse
        return .read_index;
    if (std.mem.eql(u8, value, "stale")) return .stale;
    if (std.mem.eql(u8, value, "read_index") or std.mem.eql(u8, value, "read-index")) return .read_index;
    if (std.mem.eql(u8, value, "leader_lease") or std.mem.eql(u8, value, "leader-lease")) return .leader_lease;
    return error.InvalidReadConsistency;
}

pub fn runtimeSchemaDebugRequested(query: []const u8) bool {
    const value = parseSimpleQueryParam(query, "debug") orelse return false;
    return std.mem.eql(u8, value, "runtime_schema");
}

fn parseUnsignedQueryParam(query: []const u8, key: []const u8) !?u64 {
    const value = parseSimpleQueryParam(query, key) orelse return null;
    return try std.fmt.parseUnsigned(u64, value, 10);
}

test "artifact repair query params decode percent encoded values" {
    const alloc = std.testing.allocator;
