    try std.testing.expectEqualStrings("docs", permissions.value[0].resource);

    var user_resp = try executeHttpxTestRequest(&server, .{
        .method = .GET,
        .uri = "/auth/v1/users/alice",
        .authorization = admin_auth,
    });
    defer user_resp.deinit(alloc);
