    };

    const FakeReads = struct {
        worker_calls: usize = 0,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                    .query_group_local = queryGroupLocal,
                    .join_partition_group_local = joinPartitionGroupLocal,
                },
            };
        }

